window.BUZZ_COURSE_V2_LESSONS = Object.assign(window.BUZZ_COURSE_V2_LESSONS || {}, {"propositions-quantifiers":{"id":"propositions-quantifiers","prerequisites":["function-intro"],"next":["negation"],"related":["epsilon-delta-definition","contradiction"],"objectives":["分清楚命題與含變數的敘述，知道「若 $P$ 則 $Q$」什麼時候算真。","把中文的「所有、每一個、存在、有一個」翻成 $\\forall$、$\\exists$，並寫清楚變數跑在哪個集合。","看得出量詞順序不同就是不同的命題：$\\forall x\\exists y$ 與 $\\exists y\\forall x$。"],"concept":[{"heading":"① 為什麼要學這個","body":["分析學的定義幾乎全部長這樣：「對每一個 $\\varepsilon>0$，存在 $\\delta>0$，使得對所有 $x$……」。一句話裡有三個量詞，順序換一個字，意思就完全不同。這一課只做一件事：把這種句子讀準。"]},{"heading":"② 命題與連接詞","body":["命題是有確定真假的敘述：「$2<3$」是真命題，「4 是質數」是假命題。「$x>2$」不是命題，要等 $x$ 給定才有真假；這種含變數的敘述記成 $P(x)$。","連接詞：$P\\land Q$（且）兩個都真才真；$P\\lor Q$（或）至少一個真就真；$P\\Rightarrow Q$（若 $P$ 則 $Q$）只在「$P$ 真而 $Q$ 假」時為假。所以前提為假時 $P\\Rightarrow Q$ 自動為真，例如「若 $1>2$，則月亮是方的」是真命題。這不是文字遊戲：定理「若 $f$ 可微則 $f$ 連續」只對可微的 $f$ 有話要說。"]},{"heading":"③ 兩個量詞","body":["全稱量詞 $\\forall x\\in A,P(x)$：$A$ 裡每一個 $x$ 都讓 $P(x)$ 為真。要證它，得對「任意給定的 $x$」論證；要否定它，只需一個反例。","存在量詞 $\\exists x\\in A,P(x)$：$A$ 裡至少有一個 $x$ 讓 $P(x)$ 為真。要證它，把那個 $x$ 找出來（或證明它一定存在）。","集合 $A$ 不能省：$\\exists x\\in\\mathbb{R},x^2=2$ 是真的；$\\exists x\\in\\mathbb{Q},x^2=2$ 是假的（〈反證法〉會證）。"]},{"heading":"④ 順序就是意思","body":["$\\forall x\\in\\mathbb{R}\\ \\exists y\\in\\mathbb{R},y>x$：每個 $x$ 都有比它大的數，$y$ 可以跟著 $x$ 改（取 $y=x+1$）。真。","$\\exists y\\in\\mathbb{R}\\ \\forall x\\in\\mathbb{R},y>x$：有一個 $y$ 比所有實數都大。假：任何 $y$ 拿 $x=y$ 來試就失敗。","讀法：從左往右，後面的變數可以依賴前面的變數。〈ε-δ 定義〉的 $\\delta$ 寫在 $\\varepsilon$ 後面，所以 $\\delta$ 可以依賴 $\\varepsilon$。"],"tex":["\\forall x\\,\\exists y\\ (y>x)\\quad\\not\\equiv\\quad\\exists y\\,\\forall x\\ (y>x)"]}],"workedExamples":[{"title":"翻譯成符號並判斷真假","prompt":"把「每個正實數都有一個平方根」寫成量詞句，並判斷真假。","steps":["主角是「每個正實數 $x$」，所以外層是 $\\forall x>0$。","「有一個平方根」是說存在 $y$ 使 $y^2=x$，所以內層是 $\\exists y\\in\\mathbb{R},y^2=x$。","合起來：$\\forall x>0\\ \\exists y\\in\\mathbb{R},y^2=x$。","真：給定 $x>0$，取 $y=\\sqrt{x}$。$y$ 依賴 $x$，量詞順序允許這樣。例如 $x=2$ 時 $y=\\sqrt{2}$，$y^2=2$。"],"answer":"$\\forall x>0\\ \\exists y\\in\\mathbb{R},y^2=x$；真命題","note":"$\\sqrt{x}$ 的存在要靠實數的完備性；在 $\\mathbb{Q}$ 裡這句話是假的。"},{"title":"量詞對調","prompt":"判斷真假：(a) $\\forall x\\in\\mathbb{R}\\ \\exists y\\in\\mathbb{R},y>x$　(b) $\\exists y\\in\\mathbb{R}\\ \\forall x\\in\\mathbb{R},y>x$","steps":["(a) 任意給定 $x$，要找一個 $y$。取 $y=x+1$，則 $y-x=1>0$。所以 (a) 真。","(b) 要找一個固定的 $y$，讓所有 $x$ 都比它小。任意拿一個候選 $y$，令 $x=y$，則 $y>x$ 變成 $y>y$，不成立。","每個候選 $y$ 都被打掉，所以不存在這樣的 $y$，(b) 假。"],"answer":"(a) 真，(b) 假"},{"title":"若…則…的真假與逆命題","prompt":"判斷 (a)「$\\forall x\\in\\mathbb{R},\\ x>2\\Rightarrow x^2>4$」與它的逆命題 (b)「$\\forall x\\in\\mathbb{R},\\ x^2>4\\Rightarrow x>2$」。","steps":["(a) 只要檢查 $x>2$ 的 $x$（其他 $x$ 前提為假，蘊含自動為真）。$x>2>0$，兩邊乘正數 $x$：$x^2>2x$；又 $2x>4$。所以 $x^2>4$。真。","(b) 要一個反例：前提真、結論假。$x=-3$：$x^2=9>4$，但 $x>2$ 不成立。假。","一句全稱命題，一個反例就足以推翻。"],"answer":"(a) 真，(b) 假（反例 $x=-3$）"}],"pitfalls":["把 $\\forall x\\exists y$ 當成 $\\exists y\\forall x$ 來用：以為 $\\delta$ 可以挑一個對所有點都通用的。","量詞沒寫變數範圍（$\\mathbb{R}$、$\\mathbb{Q}$、$x>0$），同一句話真假就變了。","以為前提為假的「若 $P$ 則 $Q$」是假命題。它是真的（空真）。","用一個例子「證明」全稱命題。例子只能推翻全稱、證明存在。"],"voice":"8723c524","sections":[{"title":"命題與連接詞","beats":[{"show":["「$2<3$」真，「4 是質數」假"],"note":"命題：有確定真假的敘述。","say":"分析學的定義一句話裡常有三個量詞，先把最小的零件弄清楚。有確定真假的一句話，叫命題。","board":[{"do":"write","line":"「$2<3$」真，「4 是質數」假","on":"有確定真假","ms":6250}],"t":[0,9936]},{"show":["「$x>2$」不是命題，記成 $P(x)$"],"note":"要等 $x$ 給定才有真假。","say":"x 大於二就還不是命題，因為 x 還沒給定，說不出真假。這種含變數的敘述，記成 P 在 x 的值。","board":[{"do":"write","line":"「$x>2$」不是命題，記成 ${{p:P(x)}}$"},{"do":"underline","term":"p","on":"含變數","label":"x 給定才有真假","ms":6300}],"t":[10224,20448]},{"show":["$P\\land Q$：兩個都真才真","$P\\lor Q$：至少一個真就真"],"say":"用連接詞把命題接起來。且，要兩個都真才真；或，只要有一個真就夠了。","board":[{"do":"clear"},{"do":"write","line":"$P\\land Q$：兩個都真才真","on":"且，","ms":2975},{"do":"write","line":"$P\\lor Q$：至少一個真就真","on":"或，","ms":5150}],"t":[20736,28908]},{"show":["$P\\Rightarrow Q$ 只在「$P$ 真、$Q$ 假」時為假"],"note":"前提為假時，蘊含自動為真。","say":"若 P 則 Q，只有一種情況是假的：P 真而 Q 假。前提本身是假的，整句就自動成立，這叫空真。","board":[{"do":"write","line":"$P\\Rightarrow Q$ 只在「$P$ 真、$Q$ 假」時為假","on":"若 P 則 Q","ms":50},{"do":"write","line":"前提假 ⇒ 整句自動成立（空真）","on":"前提本身","ms":5125}],"t":[29196,39528]}],"check":1},{"title":"兩個量詞","beats":[{"show":["$\\forall x\\in A,P(x)$"],"note":"$A$ 裡每一個 $x$ 都讓 $P(x)$ 為真。","say":"倒過來的 A 念作對所有。要證它，得對任意給定的 x 論證，不能只挑幾個試。","board":[{"do":"write","line":"${{q:\\forall}}\\,x\\in A,P(x)$"},{"do":"focus","term":"q","label":"對所有","on":"對所有","ms":1250},{"do":"write","line":"任意給定 $x$ 論證","on":"任意給定","ms":3975}],"t":[39816,47772]},{"show":["$\\exists x\\in A,P(x)$"],"note":"至少有一個 $x$ 讓 $P(x)$ 為真。","say":"反過來的 E 念作存在。要證它，把那個 x 找出來，或證明它一定存在。","board":[{"do":"write","line":"${{e:\\exists}}\\,x\\in A,P(x)$"},{"do":"focus","term":"e","label":"存在","on":"念作存在","ms":838},{"do":"write","line":"把那個 $x$ 找出來","on":"把那個","ms":3513}],"t":[48060,55728]},{"show":["$\\exists x\\in\\mathbb{R},x^2=2$ 真","$\\exists x\\in\\mathbb{Q},x^2=2$ 假"],"note":"集合 $A$ 不能省。","say":"同樣一句話，在實數裡是真的，在有理數裡是假的。所以範圍一定要寫清楚。","board":[{"do":"clear"},{"do":"write","line":"$\\exists x\\in{{r:\\mathbb{R}}},x^2=2$ 真","on":"在實數裡","ms":1400},{"do":"write","line":"$\\exists x\\in{{q:\\mathbb{Q}}},x^2=2$ 假","on":"在有理數","ms":3063},{"do":"underline","term":"q","label":"範圍","on":"範圍一定","ms":5963}],"t":[56016,64404]},{"show":["$x^2=2$ 在 $\\mathbb{Q}$ 裡無解"],"note":"證明在〈反證法〉；現在只先接受。","say":"為什麼有理數裡找不到？因為平方等於二的數是根號二，它不能寫成整數比。這個證明留到反證法那一課，現在先接受。","board":[{"do":"write","line":"$x^2=2$ 的解是 ${{s:\\sqrt{2}}}$","on":"平方等於二","ms":3138},{"do":"underline","term":"s","label":"不是分數","on":"不能寫成","ms":5800}],"t":[64692,77184]},{"show":["$x>2\\Rightarrow x^2>4$ 真","逆命題：$x=-3$ 是反例"],"note":"$x^2=9>4$，但 $x>2$ 不成立。","say":"要推翻一句全稱命題，一個反例就夠。逆命題拿負三試：平方是九，比四大，可是負三不大於二。","board":[{"do":"clear"},{"do":"write","line":"$x>2\\Rightarrow x^2>4$ 真","on":"全稱命題","ms":975},{"do":"write","line":"逆命題：${{c:x=-3}}$ 是反例","on":"逆命題拿","ms":4225},{"do":"write","line":"$x^2=9>4$，$x>2$ 不成立","on":"平方是九","ms":6013},{"do":"circle","term":"c","on":"可是","ms":8088}],"t":[77472,88020]},{"show":["逆命題：$\\forall x,\\ x^2>4\\Rightarrow x>2$"],"note":"把前提與結論對調。","say":"原本是 x 大於二推出平方大於四。逆命題是平方大於四推出 x 大於二，前提跟結論對調，外面一樣有對所有 x。","board":[{"do":"clear"},{"do":"write","line":"原：$\\forall x,\\ {{p:x>2}}\\Rightarrow {{q:x^2>4}}$","on":"原本是","ms":50},{"do":"write","line":"逆：$\\forall x,\\ {{q:x^2>4}}\\Rightarrow {{p:x>2}}$","on":"逆命題是","ms":3838},{"do":"arrow","from":"p","to":"q","on":"對調","label":"對調","ms":8150}],"t":[88308,99756]}],"check":2},{"title":"順序就是意思","beats":[{"show":["$\\forall x\\in\\mathbb{R}\\ \\exists y\\in\\mathbb{R},y>x$"],"note":"取 $y=x+1$：真。","say":"每個 x 都有比它大的數。y 寫在 x 後面，可以跟著 x 改，取 x 加一就好，所以是真的。","board":[{"do":"write","line":"${{fx:\\forall x\\in\\mathbb{R}}}\\ {{ey:\\exists y\\in\\mathbb{R}}},y>x$","tint":{"fx":"blue","ey":"violet"}},{"do":"underline","term":"ey","label":"可隨 x 改","on":"可以跟著","ms":4350},{"do":"write","line":"取 $y=x+1$：真","on":"取 x 加一","ms":5675}],"t":[100044,109116]},{"show":["$\\exists y\\in\\mathbb{R}\\ \\forall x\\in\\mathbb{R},y>x$"],"note":"任何 $y$ 拿 $x=y$ 來試就失敗：假。","say":"把兩個量詞對調，變成有一個 y 比所有實數都大。隨便拿一個 y，令 x 等於 y，就不成立了。","board":[{"do":"write","line":"${{ey:\\exists y\\in\\mathbb{R}}}\\ {{fx:\\forall x\\in\\mathbb{R}}},y>x$"},{"do":"write","line":"令 $x=y$：${{b:y>y}}$","on":"隨便拿","ms":4900},{"do":"strike","term":"b","label":"不成立","on":"等於 y","ms":6750}],"t":[109404,118944]},{"show":["從左往右讀","後面的變數可以依賴前面的"],"say":"讀量詞句的規則只有一條：從左往右，寫在後面的變數，可以隨前面的變數改。","board":[{"do":"clear"},{"do":"write","line":"從左往右讀","on":"規則只有","ms":950},{"do":"write","line":"$\\forall x\\ \\exists y$：${{y:y}}$ 可依賴 ${{x:x}}$","tint":{"y":"violet","x":"blue"},"on":"寫在後面","ms":3575},{"do":"arrow","from":"y","to":"x","on":"隨前面","ms":5513}],"t":[119232,127008]}],"key":"$\\forall\\exists$ 換成 $\\exists\\forall$，意思就變","check":0},{"title":"翻譯成符號","beats":[{"show":["「每個正實數都有一個平方根」"],"say":"來翻一句中文：每個正實數都有一個平方根。先問，這句話的主角是誰？","board":[{"do":"write","line":"「每個正實數 ${{s:x>0}}$ 都有一個平方根」"},{"do":"underline","term":"s","label":"誰是主角","on":"先問","ms":4663}],"t":[127296,135360]},{"show":["主角：每個正實數 $x$"],"note":"外層是 $\\forall x>0$。","say":"主角是每一個正實數 x，所以最外層是對所有 x 大於零。","board":[{"do":"write","line":"主角：每個正實數 $x$"},{"do":"write","line":"外層：${{f:\\forall x>0}}$","on":"最外層","ms":2663},{"do":"focus","term":"f","color":"blue","label":"對所有","on":"對所有","ms":3388}],"t":[135648,141408]},{"show":["外層 $\\forall x>0$，內層 $\\exists y$"],"note":"先被給定的寫前面，後挑的寫後面。","say":"兩塊怎麼接？x 是先被給定的，所以放前面；y 是看了 x 才去找的，所以放後面。這樣 y 才能隨 x 改。","board":[{"do":"write","line":"${{f:\\forall x>0}}\\ {{e:\\exists y\\in\\mathbb{R},y^2=x}}$","tint":{"f":"blue","e":"violet"}},{"do":"arrow","from":"f","to":"e","on":"放前面","label":"先給定","ms":3925}],"t":[141696,153252]},{"show":["有一個平方根：$\\exists y\\in\\mathbb{R},y^2=x$"],"say":"有一個平方根，是說存在一個 y，它的平方等於 x。兩塊要怎麼接起來？","board":[{"do":"write","line":"${{e:\\exists y\\in\\mathbb{R},y^2=x}}$"},{"do":"underline","term":"e","color":"violet","label":"存在 y","on":"存在一個","ms":1813}],"t":[153540,161316]}],"predict":{"ask":"合起來，量詞怎麼排？","options":[{"label":"$\\forall x>0\\ \\exists y\\in\\mathbb{R},y^2=x$","correct":true},{"label":"$\\exists y\\in\\mathbb{R}\\ \\forall x>0,y^2=x$","why":"你把 $\\exists y$ 放到前面，變成一個 $y$ 要當所有 $x$ 的平方根。$y$ 要隨 $x$ 改，得寫在後面。"},{"label":"$\\forall x>0\\ \\forall y\\in\\mathbb{R},y^2=x$","why":"「有一個」是存在，不是所有：不是每個 $y$ 都是 $x$ 的平方根。"}]}},{"title":"誰跟著誰變","beats":[{"show":["給定 $x>0$，取 $y=\\sqrt{x}$"],"note":"$y$ 依賴 $x$，量詞順序允許。","say":"上一句是真的：給定 x 大於零，取根號 x 就好。y 跟著 x 變，因為 y 寫在 x 後面。","board":[{"do":"write","line":"給定 $x>0$，取 ${{y:y=\\sqrt{x}}}$"},{"do":"underline","term":"y","label":"y 依賴 x","on":"跟著 x 變","ms":5425}],"t":[161604,170712]},{"show":["$\\varepsilon$ 在前，$\\delta$ 在後"],"note":"所以 $\\delta$ 可以依賴 $\\varepsilon$。","say":"之後學 epsilon delta 定義，delta 寫在 epsilon 後面，所以 delta 可以隨 epsilon 改。","board":[{"do":"write","line":"${{e:\\varepsilon}}$ 在前，${{d:\\delta}}$ 在後","tint":{"e":"blue","d":"violet"}},{"do":"underline","term":"d","label":"可依賴前面","on":"可以隨","ms":4950}],"t":[171000,178056]},{"show":["別把 $\\forall x\\exists y$ 當 $\\exists y\\forall x$ 用"],"note":"以為 $\\delta$ 可以挑一個對所有點通用的。","say":"常見的錯，是把順序讀反，以為 delta 可以挑一個對所有點都通用的。順序換了，意思就換了。","board":[{"do":"write","line":"$\\forall x\\,\\exists y\\ \\ne\\ \\exists y\\,\\forall x$"},{"do":"write","line":"順序換了，意思就換了","on":"順序換了","ms":6575}],"t":[178344,188028]}],"key":"先寫誰被給定，再寫誰被挑選","check":3}],"checks":[{"ask":"「$\\forall x\\in\\mathbb{R}\\ \\exists y\\in\\mathbb{R},x+y=0$」是？","options":[{"label":"真：給定 $x$ 取 $y=-x$","correct":true},{"label":"假：沒有一個 $y$ 對所有 $x$ 都讓 $x+y=0$","why":"你把它讀成 $\\exists y\\forall x$ 了。這裡 $y$ 寫在 $x$ 後面，可以隨 $x$ 改。"},{"label":"不是命題，因為裡面有變數","why":"$x$、$y$ 都被量詞綁住了，整句有確定的真假，是命題。只有沒被綁住的變數才讓它不是命題。"}]},{"ask":"命題「若 $1>2$，則 $3<0$」是？","options":[{"label":"真","correct":true},{"label":"假，因為 $3<0$ 是假的","why":"$P\\Rightarrow Q$ 只在 $P$ 真、$Q$ 假時為假。這裡 $P$（$1>2$）本身是假的，蘊含自動為真。"},{"label":"沒有真假","why":"$1>2$ 與 $3<0$ 都有確定真假，用連接詞組起來的還是命題。"}]},{"ask":"要證明「$\\forall n\\in\\mathbb{N},n^2\\ge n$」，下列哪個做法對？","options":[{"label":"任意給定 $n\\in\\mathbb{N}$，因為 $n\\ge1$，兩邊乘 $n$ 得 $n^2\\ge n$","correct":true},{"label":"檢查 $n=1,2,3$ 都成立","why":"你用例子證全稱命題。三個例子成立不代表所有 $n$ 都成立。"},{"label":"找到 $n=1$ 使 $n^2=n$","why":"那證的是存在命題 $\\exists n,n^2=n$，不是對所有 $n$ 成立。"}]},{"ask":"下列哪一句說的是「有一個數 $M$ 比集合 $S$ 的每個元素都大或相等」？","options":[{"label":"$\\exists M\\in\\mathbb{R}\\ \\forall x\\in S,x\\le M$","correct":true},{"label":"$\\forall x\\in S\\ \\exists M\\in\\mathbb{R},x\\le M$","why":"量詞順序反了：這句讓 $M$ 跟著 $x$ 變，取 $M=x$ 就成立，任何集合都滿足，等於什麼都沒說。"},{"label":"$\\forall M\\in\\mathbb{R}\\ \\exists x\\in S,x\\le M$","why":"這是說每個數底下都有 $S$ 的元素，跟「有上界」無關。"}]}],"practice":[{"id":"cg-12a-004","core":true},{"id":"cg-12a-005","core":true},{"id":"cg-12a-001","core":true},{"id":"cg-12a-007","core":true},{"id":"cg-12a-006"},{"id":"cg-12a-002"},{"id":"cg-12a-003"},{"id":"cg-12a-008"}]},"negation":{"id":"negation","prerequisites":["propositions-quantifiers"],"next":["direct-proof"],"related":["epsilon-n-definition"],"objectives":["會否定且、或、若…則：$\\neg(P\\land Q)$、$\\neg(P\\lor Q)$、$\\neg(P\\Rightarrow Q)$。","會機械地否定多層量詞：每個 $\\forall$ 換 $\\exists$、每個 $\\exists$ 換 $\\forall$，最後把條件否定。","寫得出「數列不收斂到 $L$」「$f$ 無界」的正確否定，並拿它來證明。"],"concept":[{"heading":"① 否定是證明的另一半","body":["要證明「某件事不成立」，例如「$(-1)^n$ 不收斂到 1」，你得先知道「不收斂到 1」用符號怎麼寫。直接在定義前面加一個「不」沒有用，因為你沒辦法拿「不（對每個 $\\varepsilon$ 存在 $N$……）」去做事。否定要一路推進去，推到最裡面變成一個可以檢查的不等式。"]},{"heading":"② 連接詞的否定","body":["$\\neg(P\\land Q)\\equiv\\neg P\\lor\\neg Q$：「既…又…」不成立，表示至少有一個不成立。","$\\neg(P\\lor Q)\\equiv\\neg P\\land\\neg Q$：「…或…」不成立，表示兩個都不成立。","$\\neg(P\\Rightarrow Q)\\equiv P\\land\\neg Q$：蘊含只在「$P$ 真而 $Q$ 假」時為假，所以它的否定是「$P$ 成立，但 $Q$ 不成立」。注意否定裡沒有箭頭。"]},{"heading":"③ 量詞的否定：一路翻過去","body":["$\\neg(\\forall x,P(x))\\equiv\\ \\exists x,\\neg P(x)$：不是每個都成立，就是有一個不成立（反例）。$\\neg(\\exists x,P(x))\\equiv\\ \\forall x,\\neg P(x)$。","多層量詞照順序一個一個翻，變數範圍（$\\varepsilon>0$、$n\\ge N$）不動，只動量詞與最後的條件："],"tex":["\\neg\\big(\\forall\\varepsilon>0\\ \\exists N\\ \\forall n\\ge N,\\ |a_n-L|<\\varepsilon\\big)\\equiv\\exists\\varepsilon>0\\ \\forall N\\ \\exists n\\ge N,\\ |a_n-L|\\ge\\varepsilon"]},{"heading":"④ 否定句的人話","body":["「$a_n$ 不收斂到 $L$」：有一個固定的誤差 $\\varepsilon$，不管你把起點 $N$ 推得多遠，後面總還有某一項跟 $L$ 差至少 $\\varepsilon$。","這個 $\\varepsilon$ 是你挑的，而且只要挑一個。之後證明「不收斂」「不一致連續」，全都是先寫出這種否定，再把那個 $\\varepsilon$ 找出來。"]}],"workedExamples":[{"title":"證明 $(-1)^n$ 不收斂到 1","prompt":"$a_n=(-1)^n$。用否定形式證明 $a_n$ 不收斂到 1。","steps":["要證的是：$\\exists\\varepsilon>0\\ \\forall N\\ \\exists n\\ge N,|a_n-1|\\ge\\varepsilon$。","取 $\\varepsilon=1$（挑一個就好）。","任意給定 $N$。取 $n=2N+1$，它是奇數而且 $n\\ge N$。","$a_n=-1$，$|a_n-1|=|-1-1|=2\\ge1$。每個 $N$ 都找得到這樣的 $n$，證畢。"],"answer":"取 $\\varepsilon=1$；對每個 $N$，奇數 $n=2N+1\\ge N$ 給出 $|a_n-1|=2\\ge1$","note":"$0<\\varepsilon\\le2$ 都可以，因為 $|a_n-1|$ 在奇數項等於 2；$\\varepsilon>2$ 就不行。"},{"title":"否定「有界」並用它","prompt":"$f$ 在 $\\mathbb{R}$ 上有界的意思是 $\\exists M\\ \\forall x\\in\\mathbb{R},|f(x)|\\le M$。寫出否定，並證明 $f(x)=x$ 無界。","steps":["否定：$\\forall M\\ \\exists x\\in\\mathbb{R},|f(x)|>M$。（$\\exists$ 換 $\\forall$、$\\forall$ 換 $\\exists$，$\\le$ 換 $>$。）","證明 $f(x)=x$ 無界：任意給定 $M$。取 $x=|M|+1$。","$|f(x)|=|M|+1>|M|\\ge M$。每個 $M$ 都被超過，$f$ 無界。"],"answer":"否定：$\\forall M\\ \\exists x,|f(x)|>M$；對 $f(x)=x$ 取 $x=|M|+1$"},{"title":"否定蘊含","prompt":"否定「$\\forall x\\in\\mathbb{R},x^2<1\\Rightarrow x<1$」，並判斷原命題真假。","steps":["外層 $\\forall$ 換 $\\exists$；裡面 $\\neg(P\\Rightarrow Q)\\equiv P\\land\\neg Q$。否定是：$\\exists x\\in\\mathbb{R},x^2<1$ 且 $x\\ge1$。","檢查否定能否成立：$x\\ge1$ 時兩邊乘正數 $x$ 得 $x^2\\ge x\\ge1$，與 $x^2<1$ 矛盾。所以否定為假。","否定為假，原命題為真。"],"answer":"否定：$\\exists x,x^2<1$ 且 $x\\ge1$；原命題為真"}],"pitfalls":["只否定最後的不等式，量詞沒翻：寫成「$\\forall\\varepsilon\\ \\exists N\\ \\forall n\\ge N,|a_n-L|\\ge\\varepsilon$」。","把 $\\varepsilon>0$ 也否定成 $\\varepsilon\\le0$。變數範圍不是被否定的對象。","把 $<$ 否定成 $>$。$<$ 的否定是 $\\ge$，相等的情況要算進去。","$\\neg(P\\Rightarrow Q)$ 寫成 $\\neg P\\Rightarrow\\neg Q$ 或 $P\\Rightarrow\\neg Q$。否定裡沒有箭頭，是 $P\\land\\neg Q$。"],"voice":"f806ebec","sections":[{"title":"連接詞的否定","beats":[{"show":["否定要一路推進去"],"note":"推到最裡面，變成可以檢查的不等式。","say":"在一整句定義前面加一個不，沒辦法拿來做事。否定要一路推進去，推到最裡面的條件。","board":[{"do":"write","line":"否定要一路推進去 → 最裡面的條件"}],"t":[0,8964]},{"show":["$\\neg(P\\land Q)\\equiv\\neg P\\lor\\neg Q$"],"note":"既…又…不成立：至少有一個不成立。","say":"且的否定是或：兩個同時成立這件事不對，表示至少有一個不成立。","board":[{"do":"write","line":"$\\neg(P\\land Q)\\equiv {{ra:\\neg P\\lor\\neg Q}}$"},{"do":"underline","term":"ra","on":"兩個同時","ms":1638}],"t":[9252,15984]},{"show":["$\\neg(x>0\\land x<1)$","$\\equiv x\\le0\\lor x\\ge1$"],"note":"$<$ 的否定是 $\\ge$，$>$ 的否定是 $\\le$。","say":"舉個例子：x 大於零且 x 小於一不成立，就是 x 小於等於零，或 x 大於等於一。","board":[{"do":"write","line":"$\\neg(x>0\\land x<1)$"},{"do":"write","line":"$\\equiv {{o1:x\\le0\\lor x\\ge1}}$","on":"就是","ms":3875}],"t":[16272,24228]},{"show":["$\\neg(P\\lor Q)\\equiv\\neg P\\land\\neg Q$"],"note":"…或…不成立：兩個都不成立。","say":"或的否定是且：連一個都沒成立，就是兩個都不成立。","board":[{"do":"write","line":"$\\neg(P\\lor Q)\\equiv {{rb:\\neg P\\land\\neg Q}}$"},{"do":"underline","term":"rb","on":"連一個都","ms":1625}],"t":[24516,30060]},{"show":["$\\neg(P\\Rightarrow Q)\\equiv P\\land\\neg Q$"],"note":"否定裡沒有箭頭。","say":"若 P 則 Q 只在 P 真、Q 假時為假，所以它的否定就是：P 成立，但 Q 不成立。","board":[{"do":"write","line":"$\\neg(P\\Rightarrow Q)\\equiv {{rc:P\\land\\neg Q}}$"},{"do":"underline","term":"rc","label":"沒有箭頭","on":"它的否定","ms":3775}],"t":[30348,38484]}],"check":1},{"title":"量詞的否定","beats":[{"show":["$\\neg(\\forall x,P(x))\\equiv\\exists x,\\neg P(x)$"],"note":"不是每個都成立：有一個不成立，也就是反例。","say":"對所有的否定是存在：不是每一個都成立，就是有一個不成立，那一個就是反例。","board":[{"do":"write","line":"$\\neg(\\forall x,P(x))\\equiv {{b:\\exists}} x,\\neg P(x)$","tint":{"b":"violet"}},{"do":"underline","term":"b","label":"那一個是反例","on":"有一個不成立","ms":3925}],"t":[38772,46224]},{"show":["$\\neg(\\exists x,P(x))\\equiv\\forall x,\\neg P(x)$"],"say":"存在的否定是對所有：找不到任何一個成立，就是每一個都不成立。","board":[{"do":"write","line":"$\\neg({{b:\\exists}} x,P(x))\\equiv {{a:\\forall}} x,\\neg P(x)$","tint":{"a":"blue","b":"violet"}},{"do":"underline","term":"a","on":"找不到任何","ms":2200}],"t":[46512,52992]},{"show":["多層量詞：照順序一個一個翻"],"note":"最後的條件也要否定。","say":"好幾層量詞，就從左到右一個一個翻：對所有換存在、存在換對所有，最後的條件再否定。","board":[{"do":"write","line":"${{a:\\forall}} x\\ {{b:\\exists}} y,\\ {{c:P(x,y)}}$","tint":{"a":"blue","b":"violet"}},{"do":"transform","line":"${{b:\\exists}} x\\ {{a:\\forall}} y,\\ \\neg\\,{{c:P(x,y)}}$","on":"對所有換存在","ms":3438},{"do":"underline","term":"c","label":"條件再否定","on":"最後的條件","ms":6425}],"t":[53280,62172]}],"key":"每翻一個量詞，$\\forall$ 與 $\\exists$ 互換","check":0},{"title":"否定收斂","beats":[{"show":["$\\forall\\varepsilon>0\\ \\exists N\\ \\forall n\\ge N,|a_n-L|<\\varepsilon$"],"note":"$a_n$ 收斂到 $L$。","say":"這是收斂的定義，疊了好幾層量詞。把它整句否定，看會變成什麼。","board":[{"do":"write","line":"$\\forall{{e:\\varepsilon>0}}\\ \\exists N\\ \\forall{{n:n\\ge N}},\\ |a_n-L|<\\varepsilon$"}],"t":[62460,70092]},{"show":["$\\exists\\varepsilon>0\\ \\forall N\\ \\exists n\\ge N,|a_n-L|\\ge\\varepsilon$"],"note":"範圍 $\\varepsilon>0$、$n\\ge N$ 不動。","say":"量詞全部翻過來，小於變成大於等於。epsilon 大於零、n 大於等於 N 這些範圍不動。","board":[{"do":"write","line":"$\\exists{{e:\\varepsilon>0}}\\ \\forall N\\ \\exists{{n:n\\ge N}},\\ |a_n-L|{{ge:\\ge}}\\varepsilon$","on":"量詞全部","ms":50},{"do":"focus","term":"ge","on":"小於變成","ms":1838},{"do":"underline","term":"e","label":"範圍不動","on":"epsilon 大於零","ms":4300},{"do":"underline","term":"n","on":"n 大於等於 N","ms":5625}],"t":[70380,79020]},{"show":["有一個固定的誤差 $\\varepsilon$","後面總還有某一項差至少 $\\varepsilon$"],"say":"翻成人話：有一個固定的誤差，不管起點 N 推得多遠，後面總還有某一項跟 L 差至少這麼多。","board":[{"do":"write","line":"有一個固定的誤差 $\\varepsilon$","on":"有一個固定","ms":1225},{"do":"write","line":"後面總還有某一項差至少 $\\varepsilon$","on":"後面總還有","ms":4763}],"t":[79308,87912]}],"check":2},{"title":"證明：不收斂到 1","beats":[{"show":["要證：$\\exists\\varepsilon>0\\ \\forall N\\ \\exists n\\ge N,|a_n-1|\\ge\\varepsilon$"],"note":"照否定形式，由外往內一層一層做。","say":"a n 是負一的 n 次方，要證它不收斂到一。照上一節的否定形式，一層一層做。","board":[{"do":"write","line":"$a_n=(-1)^n$，要證："},{"do":"write","line":"${{q1:\\exists\\varepsilon>0}}\\ {{q2:\\forall N}}\\ {{q3:\\exists n\\ge N}},\\ |a_n-1|\\ge\\varepsilon$","on":"照上一節","ms":4338}],"t":[88200,96480]},{"show":["取 $\\varepsilon=1$"],"note":"存在：挑一個就好。","say":"最外層是存在 epsilon，由我們挑，而且挑一個就夠。取 epsilon 等於一。","board":[{"do":"focus","term":"q1","on":"最外層","ms":50},{"do":"write","line":"取 ${{e1:\\varepsilon=1}}$","on":"取 epsilon","ms":5275}],"t":[96768,104256]},{"show":["任意給定 $N$"],"say":"接著對所有 N：N 是別人給的，不能挑。我們要在 N 後面找一項，離一夠遠。","board":[{"do":"focus","term":"q2","on":"對所有 N","ms":450},{"do":"transform","line":"取 ${{e1:\\varepsilon=1}}$；任意給定 $N$","on":"別人給的","ms":1788}],"t":[104544,112608]},{"show":["取 $n=2N+1$"],"note":"奇數，而且 $n\\ge N$。","why":{"ask":"$n$ 為什麼取 $2N+1$？","say":"在 N 後面要找哪一項？n 為什麼取二 N 加一？","options":[{"label":"要奇數項（$a_n=-1$），又要 $n\\ge N$","correct":true},{"label":"偶數項離 1 最遠","why":"偶數項 $a_n=1$，$|a_n-1|=0$，不會 $\\ge1$。要挑奇數項。"},{"label":"直接取 $n=N$ 最簡單","why":"$N$ 是別人給的，可能是偶數，那一項剛好等於 1。"}],"t":[112896,118080]},"say":"奇數項才是負一。二 N 加一一定是奇數，而且不小於 N，正好落在 N 後面。","board":[{"do":"focus","term":"q3","on":"N 後面","ms":263},{"do":"write","line":"取 ${{nn:n=2N+1}}$","on":"n 為什麼","ms":2600},{"do":"underline","term":"nn","label":"奇數，n≥N","why":true,"on":"奇數項才是","ms":50}],"t":[118368,126612]},{"show":["$|a_n-1|=|-1-1|=2\\ge1$"],"note":"每個 $N$ 都找得到，證畢。","why":{"ask":"為什麼這樣就證完了？","say":"奇數項跟一差二。為什麼這樣就證完了？","options":[{"label":"每一個給定的 $N$，都交得出這樣的 $n$","correct":true},{"label":"找到一個 $n$ 就夠了","why":"$n$ 要跟著 $N$ 找：每一個 $N$ 後面都要有這樣的一項，所以 $n$ 寫成 $N$ 的式子。"},{"label":"$a_n$ 有無窮多項等於 $-1$","why":"這是對的直覺，但證明要照否定形式寫：對每個 $N$ 交出 $n\\ge N$。"}],"t":[126900,131904]},"say":"奇數項是負一，跟一差二，大於等於一。每個 N 都找得到這樣的 n，證完了。","board":[{"do":"keep","n":1},{"do":"write","line":"$|a_n-1|=|-1-1|=2\\ge1$","on":"跟一差二","ms":763},{"do":"write","line":"每個 $N$ 都找得到這樣的 $n$","color":"green","why":true,"on":"每個 N","ms":4525}],"t":[132192,140472]},{"show":["$\\varepsilon=1$ ← $\\exists\\varepsilon$","每個 $N$ 交出 $n$ ← $\\forall N\\ \\exists n$"],"note":"任何奇數、$n\\ge N$ 都行，$2N+1$ 只是一例。","say":"取 epsilon 等於一，是最外層的存在。每個 N 交出一個 n，是對所有 N、存在 n。二大於等於一，是裡面的條件。","board":[{"do":"clear"},{"do":"write","line":"${{r1:\\varepsilon=1}}$ 對應 $\\exists\\varepsilon$","on":"取 epsilon","ms":50},{"do":"write","line":"每個 $N$ 交出 $n$ 對應 $\\forall N\\ \\exists n$","on":"每個 N","ms":3900},{"do":"write","line":"$2\\ge1$ 對應 $|a_n-1|\\ge\\varepsilon$","on":"二大於等於一","ms":8313}],"t":[140760,152568]}],"key":"挑奇數項，讓它離 $1$ 遠遠的","proof":true,"of":"ex0","skeleton":"直接","order":{"ask":"把證明排回順序：依序點每一步","steps":[{"label":"取 $\\varepsilon=1$"},{"label":"任意給定 $N$","why":"$\\varepsilon$ 在最外層，要先挑定；$N$ 是之後才給的。"},{"label":"取 $n=2N+1$","why":"$n$ 要看 $N$：先有 $N$，才寫得出 $2N+1$。"},{"label":"$|a_n-1|=2\\ge1$","why":"要先有 $n$，才算得出 $a_n$。"}]}},{"title":"範圍不動","beats":[{"show":["有界：$\\exists M\\ \\forall x,|f(x)|\\le M$","無界：$\\forall M\\ \\exists x,|f(x)|>M$"],"say":"再翻一個：有界的否定。存在換對所有、對所有換存在，小於等於換成大於。","board":[{"do":"write","line":"有界：$\\exists M\\ \\forall x,\\ |f(x)|\\le M$"},{"do":"write","line":"無界：$\\forall M\\ \\exists x,\\ |f(x)|{{gt:>}}M$","on":"有界的否定","ms":1088},{"do":"focus","term":"gt","on":"小於等於","ms":6038}],"t":[152856,161352]},{"show":["$M$ 是別人給的，$x$ 要看 $M$ 找"],"note":"無界：每個 $M$ 都要被超過。","say":"無界要對每個 M 都找得到 x。M 是別人給的，所以 x 要寫成 M 的式子。","board":[{"do":"write","line":"$M$ 別人給，$x$ 看 ${{k1:M}}$ 找","on":"M 是別人","ms":3125}],"t":[161640,169020]},{"show":["$f(x)=x$：取 $x=|M|+1$"],"note":"$|f(x)|=|M|+1>|M|\\ge M$。","say":"f 在 x 等於 x：不管給哪個 M，取 M 的絕對值加一，就超過 M 了，所以無界。","board":[{"do":"write","line":"$f(x)=x$：取 $x={{x:|M|+1}}$"},{"do":"write","line":"$|f(x)|=|M|+1>|M|\\ge M$","on":"就超過","ms":4613}],"t":[169308,176940]},{"show":["$M$ 可正可負，$x$ 是任意實數"],"note":"$|M|\\ge M$：$M\\ge0$ 時相等，$M<0$ 時 $|M|>0>M$。","say":"M 和 x 都可以是任何實數。M 不是負的時候，絕對值 M 等於 M。M 是負的時候，絕對值是正的，比 M 大。","board":[{"do":"write","line":"$M\\ge0$：${{m1:|M|=M}}$","on":"不是負的","ms":3288},{"do":"underline","term":"m1","label":"所以成立","on":"等於 M","ms":5438},{"do":"write","line":"$M<0$：$|M|>0>M$","on":"M 是負的","ms":6925}],"t":[177228,188640]},{"show":["$\\varepsilon>0$ 不會變成 $\\varepsilon\\le0$","$<$ 的否定是 $\\ge$"],"say":"兩個常見的錯：把變數範圍也否定了；把小於否定成大於，漏掉相等的情況。","board":[{"do":"clear"},{"do":"write","line":"$\\varepsilon>0$ 不會變成 ${{w1:\\varepsilon\\le0}}$","on":"常見的錯","ms":425},{"do":"strike","term":"w1","on":"範圍也否定了","ms":2138},{"do":"write","line":"$\\lnot(a<b)$ 是 $a\\ge b$，不是 ${{w2:a>b}}$","on":"把小於","ms":3600},{"do":"strike","term":"w2","on":"漏掉","ms":5488}],"t":[188928,196740]}],"check":3}],"checks":[{"ask":"「$\\exists x\\in S\\ \\forall y\\in S,y\\le x$」（$S$ 有最大元）的否定是？","options":[{"label":"$\\forall x\\in S\\ \\exists y\\in S,y>x$","correct":true},{"label":"$\\exists x\\in S\\ \\forall y\\in S,y>x$","why":"你只否定了最後的 $\\le$，量詞沒翻。每個量詞都要換。"},{"label":"$\\forall x\\in S\\ \\exists y\\in S,y\\ge x$","why":"$\\le$ 的否定是 $>$，不是 $\\ge$；$y=x$ 永遠滿足 $y\\ge x$，這句對任何集合都成立。"}]},{"ask":"$\\neg(P\\Rightarrow Q)$ 等價於？","options":[{"label":"$P\\land\\neg Q$","correct":true},{"label":"$\\neg P\\Rightarrow\\neg Q$","why":"那是「否命題」，跟原命題的否定是兩回事；$P\\Rightarrow Q$ 只有在 $P$ 真 $Q$ 假時才不成立。"},{"label":"$P\\Rightarrow\\neg Q$","why":"$P$ 為假時 $P\\Rightarrow\\neg Q$ 自動為真，但原命題此時也為真，兩者不可能互為否定。"}]},{"ask":"要證「$a_n$ 不收斂到 $L$」，$\\varepsilon$ 由誰決定？","options":[{"label":"由你挑一個固定的 $\\varepsilon>0$，對所有 $N$ 都用它","correct":true},{"label":"每個 $N$ 各挑一個 $\\varepsilon$","why":"否定裡 $\\exists\\varepsilon$ 寫在最前面，$\\varepsilon$ 不能依賴 $N$。讓 $\\varepsilon$ 跟著 $N$ 變小，就證不出任何東西。"},{"label":"要對所有 $\\varepsilon>0$ 都證","why":"那是在證收斂的另一種說法。否定的最外層是 $\\exists\\varepsilon$，找到一個就夠。"}]},{"ask":"「對所有 $x>0$，$f(x)<1$ 或 $f(x)>2$」的否定是？","options":[{"label":"存在 $x>0$，使 $1\\le f(x)\\le2$","correct":true},{"label":"存在 $x\\le0$，使 $1\\le f(x)\\le2$","why":"你把變數範圍 $x>0$ 也否定了。範圍不動，只換量詞與條件。"},{"label":"存在 $x>0$，使 $f(x)\\ge1$ 或 $f(x)\\le2$","why":"$\\neg(P\\lor Q)$ 是 $\\neg P\\land\\neg Q$，「或」要換成「且」。你寫的這句幾乎永遠成立。"}]}],"practice":[{"id":"cg-12a-015","core":true},{"id":"cg-12a-010","core":true},{"id":"cg-12a-009","core":true},{"id":"cg-12a-013","core":true},{"id":"cg-12a-016"},{"id":"cg-12a-011"},{"id":"cg-12a-014"},{"id":"cg-12a-012","challenge":true}]},"direct-proof":{"id":"direct-proof","prerequisites":["negation"],"next":["contrapositive"],"related":[],"objectives":["照「假設 $P$ → 用定義展開 → 推到 $Q$」的骨架寫證明，每一步都說得出理由。","證全稱命題時從「任意給定」開始，不偷偷代特例。","會用平方 $\\ge0$ 與三角不等式這兩個最常用的起點。"],"concept":[{"heading":"① 證明是什麼","body":["證明是一串句子，每一句都是假設、定義、已知定理，或由前面的句子依邏輯推出來的。讀者不需要相信你，只需要逐行檢查。","直接證明 $P\\Rightarrow Q$：假設 $P$ 成立，一路推到 $Q$。證 $\\forall x,P(x)\\Rightarrow Q(x)$ 時，第一句永遠是「任意給定 $x$，設 $P(x)$ 成立」，之後不能再對 $x$ 多做任何假設。"]},{"heading":"② 第一步通常是把定義寫開","body":["「$n$ 是奇數」本身沒辦法運算；寫成「存在整數 $k$ 使 $n=2k+1$」才可以代數。「$|x-a|<\\delta$」寫成「$a-\\delta<x<a+\\delta$」才可以夾。大多數初學的證明卡住，不是因為不會推，而是沒把定義攤開。","所以寫證明前先問：結論 $Q$ 的定義是什麼？我最後要寫出哪一行？從那一行往回想，再從前提往前推，兩頭接起來。"]},{"heading":"③ 兩個最好用的起點","body":["平方非負：對任何實數 $t$，$t^2\\ge0$。很多不等式就是某個平方展開後移項。","三角不等式：$|a+b|\\le|a|+|b|$。分析學裡幾乎每個「差很小」的論證都靠它把一個差拆成幾段小的差。"],"tex":["|a+b|\\le|a|+|b|"]},{"heading":"④ 草稿和證明分開","body":["找證明時可以從結論倒推（「我需要 $x^2\\ge2x$，等價於 $(x-1)^2\\ge0$」）。但寫出來時要從真的東西出發往結論推，或者每一步都寫明是「等價」。只寫一串從結論往回推的「$\\Rightarrow$」，推到一個真命題，什麼都沒證到：從假的命題也能推出真的。"]}],"workedExamples":[{"title":"兩個奇數的和是偶數","prompt":"證明：若 $m$、$n$ 都是奇數，則 $m+n$ 是偶數。","steps":["任意給定奇數 $m$、$n$。由定義，存在整數 $k$、$j$ 使 $m=2k+1$、$n=2j+1$。（兩個要用不同字母：$m$、$n$ 不一定相等。）","$m+n=2k+2j+2=2(k+j+1)$。","$k+j+1$ 是整數，所以 $m+n$ 是 2 乘一個整數，依定義是偶數。"],"answer":"$m+n=2(k+j+1)$，是偶數"},{"title":"算幾不等式","prompt":"證明：$a,b>0$ 時 $\\frac{a+b}{2}\\ge\\sqrt{ab}$，而且等號只在 $a=b$ 成立。","problemId":"px-ineq-001","steps":["$a,b>0$，所以 $\\sqrt{a}$、$\\sqrt{b}$ 都是實數。從真的東西出發：$(\\sqrt{a}-\\sqrt{b})^2\\ge0$。","展開：$(\\sqrt{a})^2-2\\sqrt{a}\\sqrt{b}+(\\sqrt{b})^2=a-2\\sqrt{ab}+b\\ge0$（$a,b>0$ 時 $\\sqrt{a}\\sqrt{b}=\\sqrt{ab}$）。","移項：$a+b\\ge2\\sqrt{ab}$，兩邊除以 2 得 $\\frac{a+b}{2}\\ge\\sqrt{ab}$。","等號 $\\iff(\\sqrt{a}-\\sqrt{b})^2=0\\iff\\sqrt{a}=\\sqrt{b}\\iff a=b$。"],"answer":"由 $(\\sqrt{a}-\\sqrt{b})^2\\ge0$ 展開移項得證；等號 $\\iff a=b$"},{"title":"反向三角不等式","prompt":"證明：對所有實數 $a$、$b$，$||a|-|b||\\le|a-b|$。","problemId":"px-ineq-003","steps":["目標 $||a|-|b||\\le|a-b|$ 等價於 $-|a-b|\\le|a|-|b|\\le|a-b|$，兩邊分開證。","右邊：$a=(a-b)+b$，由三角不等式 $|a|\\le|a-b|+|b|$，所以 $|a|-|b|\\le|a-b|$。","左邊：同理 $b=(b-a)+a$ 給 $|b|-|a|\\le|b-a|=|a-b|$，也就是 $|a|-|b|\\ge-|a-b|$。","兩邊合起來就是 $||a|-|b||\\le|a-b|$。"],"answer":"把 $a$ 寫成 $(a-b)+b$ 套三角不等式，再對調 $a$、$b$"}],"pitfalls":["用同一個 $k$ 表示兩個不同的奇數，等於偷偷假設 $m=n$。","從要證的結論出發往下推，推到 $0\\le(a-b)^2$ 就說證完。要嘛反過來寫，要嘛每步寫明「$\\iff$」。","證全稱命題時代了 $a=1$、$b=4$ 檢查，然後寫「同理可得」。","$\\sqrt{a}\\sqrt{b}=\\sqrt{ab}$ 沒說 $a,b\\ge0$。$a=b=-1$ 時左邊不是實數。"],"voice":"d8ee0f3a","sections":[{"title":"證明是什麼","beats":[{"show":["每一句：假設、定義、已知定理","或由前面推出來的"],"note":"讀者不必相信你，只要逐行檢查。","say":"證明是一串句子，每一句都要有來歷。讀的人不需要相信你，只需要一行一行檢查。","board":[{"do":"write","line":"每一句：假設、定義、已知定理"}],"t":[0,8712]},{"show":["直接證明 $P\\Rightarrow Q$：假設 $P$，推到 $Q$"],"say":"直接證明最單純：先假設 P 成立，一路推，推到 Q 為止。","board":[{"do":"write","line":"$P\\Rightarrow Q$：假設 $P$，推到 $Q$"}],"t":[9000,15264]},{"show":["第一句：任意給定 $x$，設 $P(x)$ 成立"],"note":"之後不能再對 $x$ 多做任何假設。","say":"證對所有 x 的命題，第一句永遠是任意給定 x。之後這個 x 就不能再偷偷加條件。","board":[{"do":"write","line":"第一句：任意給定 $x$，設 $P(x)$ 成立"}],"t":[15552,23904]}],"check":0},{"title":"先把定義寫開","beats":[{"show":["「$n$ 是奇數」","→ 存在整數 $k$ 使 $n=2k+1$"],"note":"寫開了才能做代數。","say":"n 是奇數這幾個字沒辦法運算。寫成存在整數 k，使 n 等於二 k 加一，才能拿來算。","board":[{"do":"write","line":"「$n$ 是奇數」"},{"do":"write","line":"→ 存在整數 $k$ 使 ${{d:n=2k+1}}$","on":"寫成存在","ms":3525},{"do":"underline","term":"d","on":"二 k 加一","ms":5938}],"t":[24192,33336]},{"show":["$|x-a|<\\delta$ → $a-\\delta<x<a+\\delta$"],"say":"絕對值也一樣，攤開成兩個不等式才能夾。初學的證明卡住，多半是定義沒攤開。","board":[{"do":"clear"},{"do":"write","line":"$|x-a|<\\delta$","on":"絕對值也","ms":50},{"do":"transform","line":"$a-\\delta<x<a+\\delta$","on":"攤開成","ms":1438}],"t":[33624,42264]},{"show":["證：$m$、$n$ 奇數 ⇒ $m+n$ 偶數"],"note":"由定義，$m=2k+1$。","say":"來證兩個奇數的和是偶數。任意給定兩個奇數，m 先寫成二 k 加一。那 n 呢？","board":[{"do":"clear"},{"do":"write","line":"證：$m$、$n$ 奇數 ⇒ $m+n$ 偶數","on":"來證","ms":50},{"do":"write","line":"$m=2k+1$","on":"m 先寫成","ms":4963}],"t":[42552,51480]}],"predict":{"ask":"$n$ 要寫成什麼？","options":[{"label":"$n=2j+1$，$j$ 是另一個整數","correct":true},{"label":"$n=2k+1$","why":"用同一個 $k$，等於偷偷假設 $m=n$；兩個奇數不一定相等。"},{"label":"$n=2j$","why":"$2j$ 是偶數的寫法；$n$ 是奇數，要加 1。"}]}},{"title":"平方非負","beats":[{"show":["$n$ 也要寫開：$n=2j+1$"],"note":"換字母，因為 $m$、$n$ 不一定相等。","say":"n 也是奇數，也要寫開，寫成二 j 加一。換字母 j，因為 m 和 n 不一定相等，共用 k 就是偷偷說它們相等。","board":[{"do":"write","line":"$m=2k+1$，${{nj:n=2j+1}}$"},{"do":"underline","term":"nj","label":"不同字母","on":"換字母","ms":4575}],"t":[51768,62820]},{"show":["$m+n=2k+2j+2=2(k+j+1)$"],"note":"2 乘一個整數，依定義是偶數。","say":"接著加起來，提出一個二，括號裡是整數，所以和是偶數。上一題就證完了。","board":[{"do":"write","line":"$m+n=2k+2j+2$"},{"do":"transform","line":"$m+n=2({{kj:k+j+1}})$","on":"提出一個二","ms":1363},{"do":"underline","term":"kj","label":"整數","on":"括號裡是整數","ms":2525}],"t":[63108,71784]},{"show":["$t^2\\ge0$","$|a+b|\\le|a|+|b|$"],"note":"兩個最好用的起點。","say":"兩個最常用的起點：實數的平方不會是負的；還有和的絕對值不超過絕對值的和，能把一個差拆成幾段。","board":[{"do":"clear"},{"do":"write","line":"$t^2\\ge0$","on":"實數的平方","ms":1913},{"do":"write","line":"$|a+b|\\le|a|+|b|$","on":"還有和的","ms":4125}],"t":[72072,81612]},{"show":["證 $a,b>0$ 時 $\\frac{a+b}{2}\\ge\\sqrt{ab}$"],"note":"等號只在 $a=b$。","say":"算幾不等式：a 和 b 都是正的，平均數大於等於根號 a b。從哪一行真的東西出發？","board":[{"do":"clear"},{"do":"write","line":"證 ${{goal:\\frac{a+b}{2}\\ge\\sqrt{ab}}}$（$a,b>0$）","on":"算幾不等式","ms":50}],"t":[81900,90792]},{"show":["$(\\sqrt a-\\sqrt b)^2\\ge0$ 展開"],"note":"$a,b>0$，所以 $(\\sqrt a)^2=a$。","say":"先展開平方。根號 a 的平方是 a，因為 a 是正的。中間根號 a 乘根號 b，合起來是根號 a b。","board":[{"do":"write","line":"$(\\sqrt a-\\sqrt b)^2\\ge0$"},{"do":"transform","line":"${{sq:(\\sqrt a)^2}}-2{{cr:\\sqrt a\\sqrt b}}+(\\sqrt b)^2\\ge0$","on":"先展開","ms":50},{"do":"focus","term":"sq","label":"等於 a","on":"根號 a 的平方","ms":2063},{"do":"underline","term":"cr","on":"中間","ms":5850}],"t":[91080,101448]},{"show":["$a-2\\sqrt{ab}+b\\ge0$","移項，除以 2"],"say":"展開那個平方會得到這一行，移項再除以二，就是要的不等式。等號只在 a 等於 b。","board":[{"do":"write","line":"$a-2\\sqrt{ab}+b\\ge0$","on":"展開那個平方","ms":50},{"do":"transform","line":"$a+b\\ge2\\sqrt{ab}$","on":"移項","ms":2563},{"do":"box","term":"goal","color":"green","on":"就是要的","ms":3988}],"t":[101736,110304]}],"check":3},{"title":"草稿和證明分開","beats":[{"show":["草稿：從結論倒推"],"note":"「我需要 $x^2\\ge2x$，等價於 $(x-1)^2\\ge0$」","say":"找證明時，從結論往回想完全可以，這是草稿，幫你找到路。","board":[{"do":"write","line":"草稿：從結論倒推"}],"t":[110592,117180]},{"show":["寫出來：從真的東西往結論推"],"note":"或者每一步寫明「$\\iff$」。","say":"可是寫出來的時候，要從真的東西出發往結論推，或者每一步都寫明是等價。","board":[{"do":"write","line":"寫出來：從真的東西往結論推"},{"do":"write","line":"或每一步寫明 $\\iff$","on":"每一步都","ms":4875}],"t":[117468,124992]},{"show":["從假的命題也能推出真的"],"note":"只寫一串往回推的 $\\Rightarrow$，什麼都沒證到。","say":"為什麼？因為從一個錯的命題出發，也可能推到一個對的結果。推到真的，不代表起點是真的。","board":[{"do":"clear"},{"do":"write","line":"從假的命題也能推出真的","on":"錯的命題","ms":2300},{"do":"write","line":"推到真的，不代表起點真的","on":"推到真的","ms":6463}],"t":[125280,135252]}],"check":1},{"title":"證明：反向三角不等式","beats":[{"show":["證 $||a|-|b||\\le|a-b|$"],"note":"拆成兩個不等式，各套一次三角不等式。","say":"最後一個：反過來的版本。策略：外面那層絕對值拆成兩個不等式，各用一次三角不等式。","board":[{"do":"write","line":"證 ${{o:||a|-|b||}}\\le|a-b|$"},{"do":"underline","term":"o","on":"外面那層","ms":3913}],"t":[135540,145044]},{"show":["$-|a-b|\\le|a|-|b|\\le|a-b|$"],"note":"$|w|\\le c$ 就是 $-c\\le w\\le c$。","why":{"ask":"為什麼要拆成兩個不等式？","say":"外面那層絕對值，為什麼要拆成兩個不等式？","options":[{"label":"$|w|\\le c$ 等於 $-c\\le w\\le c$","correct":true},{"label":"絕對值可以直接拿掉","why":"拿掉只對非負的數成立；$|a|-|b|$ 可能是負的，兩邊都要管。"},{"label":"證右邊就好，左邊自動成立","why":"右邊只管 $|a|-|b|$ 不太大；它也可能很負，要另外證不太小。"}],"t":[145332,149940]},"say":"一個數的絕對值不超過 c，就是它夾在負 c 和 c 之間。所以兩邊要分開證。","board":[{"do":"write","line":"$-|a-b|\\le{{w:|a|-|b|}}\\le|a-b|$","on":"拆成兩個","ms":2350},{"do":"underline","term":"w","label":"夾在兩界之間","why":true,"on":"夾在負 c","ms":2775}],"t":[150228,158076]},{"show":["$|a|\\le|a-b|+|b|$"],"note":"右邊：$|a|-|b|\\le|a-b|$。","say":"把 a 拆成兩段，再套剛才那個不等式，就得到這一行，移項是右半邊。","board":[{"do":"write","line":"$|a|\\le|a-b|+|b|$","on":"再套","ms":1550},{"do":"transform","line":"$|a|-|b|\\le|a-b|$","on":"移項","ms":4863}],"t":[158364,165384]},{"show":["$a$、$b$ 對調：$|b|-|a|\\le|a-b|$"],"note":"$|b-a|=|a-b|$；乘 $-1$ 就是左邊。","why":{"ask":"為什麼對調就得到左邊？","say":"a 和 b 對調再做一次。為什麼這樣就是左半邊？","options":[{"label":"$|b-a|=|a-b|$，再乘 $-1$ 翻過來","correct":true},{"label":"對調之後，不等號方向會反過來","why":"對調只是換名字，同一個不等式照樣成立；方向是乘 $-1$ 時才翻。"},{"label":"左右兩邊是同一個不等式","why":"不一樣：右邊管 $|a|-|b|$ 不太大，左邊管它不太小。"}],"t":[165672,171144]},"say":"對調得到 b 減 a 的絕對值，它就是 a 減 b 的絕對值。兩邊乘負一，就是左半邊。","board":[{"do":"write","line":"$|b|-|a|\\le|b-a|=|a-b|$","on":"對調","ms":550},{"do":"transform","line":"$-|a-b|\\le|a|-|b|$","why":true,"on":"兩邊乘負一","ms":4925}],"t":[171432,179712]},{"show":["$|b-a|=|-(a-b)|=|a-b|$","$1\\le2$ 乘 $-1$：$-1\\ge-2$"],"note":"乘負數，不等號方向要反過來。","say":"b 減 a 是 a 減 b 乘上負一，絕對值相同。而且一小於二，兩邊乘負一，變成負一大於負二，方向反過來。","board":[{"do":"write","line":"$|b-a|=|-(a-b)|=|a-b|$"},{"do":"write","line":"$1\\le2$ 乘 $-1$：$-1\\ge-2$","on":"一小於二","ms":4675}],"t":[180000,190872]},{"show":["兩邊合起來：$||a|-|b||\\le|a-b|$"],"say":"左半邊、右半邊都成立，夾起來就是要證的不等式。證完了。","board":[{"do":"keep","n":3},{"do":"write","line":"${{fin:||a|-|b||\\le|a-b|}}$","on":"夾起來","ms":2500},{"do":"box","term":"fin","color":"green","label":"證完","on":"要證的","ms":3325}],"t":[191160,198216]}],"key":"拆成兩個不等式，各套一次三角不等式","proof":true,"of":"ex2","skeleton":"直接","check":2}],"checks":[{"ask":"證明「若 $n$ 是偶數，則 $n^2$ 是偶數」，第一句最好寫什麼？","options":[{"label":"任意給定偶數 $n$，存在整數 $k$ 使 $n=2k$","correct":true},{"label":"取 $n=4$，則 $n^2=16$ 是偶數","why":"你用一個例子證全稱命題。要對任意偶數成立，得從一般的 $n=2k$ 出發。"},{"label":"假設 $n^2$ 是偶數","why":"那是把結論當成前提，方向反了。直接證明要從前提 $P$（$n$ 是偶數）出發。"}]},{"ask":"某人證 $x^2+1\\ge2x$：「$x^2+1\\ge2x\\Rightarrow x^2-2x+1\\ge0\\Rightarrow(x-1)^2\\ge0$，成立。」問題在哪？","options":[{"label":"方向反了；要嘛從 $(x-1)^2\\ge0$ 往回推，要嘛每一步寫明可逆","correct":true},{"label":"沒有問題，最後一行是真的","why":"從結論推出真命題不代表結論為真（從 $1=2$ 也推得出 $0\\cdot1=0\\cdot2$）。這題每步剛好可逆，但要寫出來。"},{"label":"$(x-1)^2\\ge0$ 不一定成立","why":"實數的平方永遠 $\\ge0$，這一行沒錯；錯的是推論的方向。"}]},{"ask":"證 $||a|-|b||\\le|a-b|$ 時，把 $a$ 寫成什麼再用三角不等式？","options":[{"label":"$a=(a-b)+b$","correct":true},{"label":"$a=(a+b)-b$","why":"這會得到 $|a|\\le|a+b|+|b|$，出現的是 $|a+b|$，不是要的 $|a-b|$。"},{"label":"$a=|a|$","why":"$a$ 可能是負數，$a=|a|$ 只在 $a\\ge0$ 成立；而且這一步沒有用到三角不等式。"}]},{"ask":"算幾不等式 $\\frac{a+b}{2}\\ge\\sqrt{ab}$ 的證明，起點是哪一行？","options":[{"label":"$(\\sqrt{a}-\\sqrt{b})^2\\ge0$","correct":true},{"label":"$(a-b)^2\\ge0$","why":"這展開得 $a^2+b^2\\ge2ab$，是另一個不等式；要得到 $\\sqrt{ab}$ 得用 $\\sqrt{a}$、$\\sqrt{b}$。"},{"label":"$a+b\\ge2\\sqrt{ab}$","why":"那是要證的結論本身（乘 2 而已），不能拿來當起點。"}]}],"practice":[{"id":"px-ineq-002","core":true},{"id":"px-ineq-001","core":true},{"id":"px-ineq-003","core":true},{"id":"cg-12a-018","core":true},{"id":"cg-12a-017"}]},"contrapositive":{"id":"contrapositive","prerequisites":["direct-proof"],"next":["contradiction"],"related":["negation"],"objectives":["知道 $P\\Rightarrow Q$ 與 $\\neg Q\\Rightarrow\\neg P$ 等價，而逆命題 $Q\\Rightarrow P$ 不等價。","看出什麼時候「從結論的否定出發」比較好推，並正確寫出 $\\neg Q$ 與 $\\neg P$。","會用逆否證明分析裡最常用的一句：$|a|<\\varepsilon$ 對所有 $\\varepsilon>0$ 成立 $\\Rightarrow a=0$。"],"concept":[{"heading":"① 換一個方向走","body":["要證「若 $n^2$ 是偶數，則 $n$ 是偶數」。直接證明要從 $n^2=2k$ 出發推出 $n$ 的事，但開根號 $\\sqrt{2k}$ 沒有用。反過來就順了：若 $n$ 是奇數，$n=2k+1$，平方一算就知道 $n^2$ 是奇數。","這就是逆否證明：不證 $P\\Rightarrow Q$，改證 $\\neg Q\\Rightarrow\\neg P$。"]},{"heading":"② 為什麼可以","body":["$P\\Rightarrow Q$ 只有在「$P$ 真、$Q$ 假」時為假；$\\neg Q\\Rightarrow\\neg P$ 只有在「$\\neg Q$ 真、$\\neg P$ 假」時為假，也就是同一個情況「$Q$ 假、$P$ 真」。兩者在每一種真假組合下都同真同假，所以等價。","逆命題 $Q\\Rightarrow P$ 不一樣：「若 $f$ 可微則 $f$ 連續」是真的，逆命題「若 $f$ 連續則 $f$ 可微」是假的（$f(x)=|x|$ 在 0 連續但不可微）。逆否可以換，逆命題不能換。"],"tex":["(P\\Rightarrow Q)\\equiv(\\neg Q\\Rightarrow\\neg P)\\qquad (P\\Rightarrow Q)\\not\\equiv(Q\\Rightarrow P)"]},{"heading":"③ 什麼時候用","body":["訊號一：結論是「某個東西等於 0／是偶數／屬於某集合」，而它的否定（$\\ne0$、是奇數、不屬於）比較能寫成式子。訊號二：前提是「對所有 $\\varepsilon$」這種很強的條件，否定結論之後可以挑一個特定的 $\\varepsilon$ 來用。","寫法：第一句寫明「我們證明逆否命題：若 $\\neg Q$，則 $\\neg P$」，然後照直接證明的方式寫。$\\neg Q$、$\\neg P$ 照〈否定〉的規則寫，尤其「或」要變「且」。"]}],"workedExamples":[{"title":"$n^2$ 是偶數 $\\Rightarrow n$ 是偶數","prompt":"證明：對整數 $n$，若 $n^2$ 是偶數，則 $n$ 是偶數。","steps":["證逆否命題：若 $n$ 不是偶數（即 $n$ 是奇數），則 $n^2$ 不是偶數（即 $n^2$ 是奇數）。","$n$ 是奇數，存在整數 $k$ 使 $n=2k+1$。","$n^2=4k^2+4k+1=2(2k^2+2k)+1$，$2k^2+2k$ 是整數，所以 $n^2$ 是奇數。","逆否命題成立，原命題成立。"],"answer":"逆否：$n$ 奇 $\\Rightarrow n^2=2(2k^2+2k)+1$ 是奇數"},{"title":"要多小就多小，就是 0","prompt":"設 $a$ 是實數。證明：若對所有 $\\varepsilon>0$ 都有 $|a|<\\varepsilon$，則 $a=0$。","steps":["證逆否命題：若 $a\\ne0$，則存在 $\\varepsilon>0$ 使 $|a|\\ge\\varepsilon$。（「對所有 $\\varepsilon$，$|a|<\\varepsilon$」的否定是「存在 $\\varepsilon$，$|a|\\ge\\varepsilon$」。）","$a\\ne0$，所以 $|a|>0$。取 $\\varepsilon=|a|$，它是正數。","此時 $|a|\\ge\\varepsilon$ 顯然成立（其實是等號）。逆否命題成立，原命題成立。"],"answer":"若 $a\\ne0$，取 $\\varepsilon=|a|>0$，則 $|a|<\\varepsilon$ 不成立","note":"之後證「極限唯一」「$\\sup$ 唯一」都會在最後一步用到這句話。"},{"title":"和夠大，就有一個夠大","prompt":"證明：對實數 $a$、$b$，若 $a+b\\ge2$，則 $a\\ge1$ 或 $b\\ge1$。","steps":["結論是「或」，直接證要分情況。改證逆否：若 $a<1$ 且 $b<1$，則 $a+b<2$。（$\\neg(a\\ge1$ 或 $b\\ge1)$ 是 $a<1$ 且 $b<1$。）","$a<1$、$b<1$ 兩式相加：$a+b<2$。","逆否命題成立，原命題成立。"],"answer":"逆否：$a<1$ 且 $b<1\\Rightarrow a+b<2$"}],"pitfalls":["證成了逆命題 $Q\\Rightarrow P$（例如證「$n$ 偶 $\\Rightarrow n^2$ 偶」），以為就證完了原命題。","否定「或」時忘了換成「且」，寫成「$a<1$ 或 $b<1$」。","否定「對所有 $\\varepsilon$，$|a|<\\varepsilon$」寫成「對所有 $\\varepsilon$，$|a|\\ge\\varepsilon$」，量詞沒換。","沒寫「我們證明逆否命題」，讀者看不出你從哪裡出發。"],"voice":"fa91e855","sections":[{"title":"證明：換一個方向走","beats":[{"show":["證：$n^2$ 偶數 ⇒ $n$ 偶數"],"note":"從 $n^2=2k$ 開根號 $\\sqrt{2k}$ 沒有用：反過來走。","say":"要證 n 平方是偶數，n 就是偶數。從 n 平方等於二 k 開根號，什麼也看不出來。策略：反過來走。","board":[{"do":"write","line":"證：$n^2$ 偶數 ⇒ $n$ 偶數"},{"do":"write","line":"$n^2=2k$，${{r:\\sqrt{2k}}}$","on":"開根號","ms":5425},{"do":"strike","term":"r","label":"看不出","on":"什麼也","ms":6388}],"t":[0,11196]},{"show":["改證：$n$ 奇數 ⇒ $n^2$ 奇數"],"note":"不證 $P\\Rightarrow Q$，改證 $\\neg Q\\Rightarrow\\neg P$。","why":{"ask":"反過來走，要從哪裡出發？","say":"反過來走，第一步要假設什麼？","options":[{"label":"否定結論：$n$ 不是偶數，也就是奇數","correct":true},{"label":"否定前提：$n^2$ 是奇數","why":"那是從 $\\neg P$ 出發；逆否是從結論的否定 $\\neg Q$ 出發，推到 $\\neg P$。"},{"label":"從結論出發：$n$ 是偶數","why":"從 $Q$ 推 $P$ 是逆命題，跟原命題不等價。"}],"t":[11484,14976]},"say":"從結論的否定出發：假設 n 是奇數，去證 n 平方也是奇數。這就叫逆否證明。","board":[{"do":"write","line":"反過來走：${{c:\\neg Q\\Rightarrow\\neg P}}$"},{"do":"write","line":"假設 $n$ 奇數 ⇒ $n^2$ 奇數","why":true,"on":"假設","ms":1875},{"do":"focus","term":"c","color":"gold","label":"逆否","why":true,"on":"逆否證明","ms":6688}],"t":[15264,23688]},{"show":["$n=2k+1$"],"note":"奇數的定義，$k$ 是整數。","say":"n 是奇數，照定義寫成二 k 加一，k 是整數。","board":[{"do":"clear"},{"do":"write","line":"$n={{d:2k+1}}$","on":"寫成","ms":1732},{"do":"underline","term":"d","label":"奇數定義","on":"二 k","ms":2088}],"t":[23976,29016]},{"show":["$n^2=4k^2+4k+1=2(2k^2+2k)+1$"],"note":"$2k^2+2k$ 是整數，所以 $n^2$ 是奇數。","say":"平方展開，前面兩項提出一個二，括號裡是整數，所以 n 平方是奇數，逆否成立。","board":[{"do":"transform","line":"$n^2=4k^2+4k+1$"},{"do":"transform","line":"$n^2=2{{t:(2k^2+2k)}}+1$","on":"提出","ms":2075},{"do":"circle","term":"t","color":"green","label":"整數","on":"括號裡","ms":3250}],"t":[29304,37872]}],"key":"奇數寫成 $2k+1$，平方後湊回奇數形","proof":true,"of":"ex0","skeleton":"直接","where":{"ask":"「$k$ 是整數」用在哪一步？","steps":[{"label":"改證：$n$ 奇數 ⇒ $n^2$ 奇數","why":"這只是邏輯：把 $P\\Rightarrow Q$ 換成 $\\neg Q\\Rightarrow\\neg P$。"},{"label":"$n=2k+1$","why":"這一步是從奇數的定義拿到 $k$，還沒用到它是整數。"},{"label":"展開：$n^2=4k^2+4k+1$","why":"展開對任何數 $k$ 都對，是代數。"},{"label":"$2k^2+2k$ 是整數，所以 $n^2$ 是奇數","correct":true}]}},{"title":"為什麼等價","beats":[{"show":["$P\\Rightarrow Q$ 假：$P$ 真、$Q$ 假"],"say":"上一節的平方是二乘一個整數再加一，所以是奇數，逆否成立。可是為什麼這樣就算證完原命題？","board":[{"do":"write","line":"$P\\Rightarrow Q$ 假：${{c1:P\\text{ 真、}Q\\text{ 假}}}$","on":"可是為什麼","ms":6550}],"t":[38160,48384]},{"show":["$\\neg Q\\Rightarrow\\neg P$ 假：$\\neg Q$ 真、$\\neg P$ 假"],"note":"也就是同一個情況：$Q$ 假、$P$ 真。","say":"逆否命題什麼時候是假的？非 Q 真、非 P 假，說穿了就是 Q 假、P 真，跟原命題一模一樣。","board":[{"do":"write","line":"$\\neg Q\\Rightarrow\\neg P$ 假：$\\neg Q$ 真、$\\neg P$ 假","on":"逆否命題","ms":50},{"do":"write","line":"就是 ${{c3:Q\\text{ 假、}P\\text{ 真}}}$","on":"說穿了","ms":4925},{"do":"focus","term":"c3","label":"跟原命題一樣","on":"Q 假","ms":5825},{"do":"focus","term":"c1","on":"跟原命題","ms":7400}],"t":[48672,58644]},{"show":["P 真 Q 真：兩句都真","P 真 Q 假：兩句都假"],"note":"先列 $P$ 為真的兩種組合。","say":"把四種組合全列出來。P 真 Q 真，原命題真，逆否也真。P 真 Q 假，兩句都假。","board":[{"do":"write","line":"P 真 Q 真：兩句都真"},{"do":"write","line":"P 真 Q 假：兩句都假","on":"P 真 Q 假","ms":6800}],"t":[58932,68688]},{"show":["P 假 Q 真：兩句都真","P 假 Q 假：兩句都真"],"note":"$P$ 假時，原命題一定真。","say":"P 假的時候，原命題一定真。逆否的結論非 P 是真的，所以也一定真。四種組合全部對上。","board":[{"do":"write","line":"P 假 Q 真：兩句都真"},{"do":"write","line":"P 假 Q 假：兩句都真","on":"逆否的結論","ms":3388}],"t":[68976,79092]},{"show":["$(P\\Rightarrow Q)\\equiv(\\neg Q\\Rightarrow\\neg P)$"],"say":"兩句話在每一種真假組合下都同真同假，所以等價。注意，是對調再加否定，兩個動作都要做。","board":[{"do":"write","line":"$(P\\Rightarrow Q)\\equiv({{sw:\\neg Q\\Rightarrow\\neg P}})$","color":"green","on":"所以等價","ms":3738},{"do":"underline","term":"sw","label":"對調＋否定","on":"對調再加否定","ms":6525}],"t":[79380,89640]}],"check":0},{"title":"逆命題不能換","beats":[{"show":["$Q\\Rightarrow P$ 是逆命題"],"note":"只對調、沒否定：跟原命題不等價。","say":"只把前後對調、沒有否定，得到的是逆命題。它跟原命題不是同一句話。","board":[{"do":"write","line":"逆命題：${{c:Q\\Rightarrow P}}$"},{"do":"underline","term":"c","label":"只對調","on":"對調","ms":875}],"t":[89928,98028]},{"show":["可微 ⇒ 連續：真","連續 ⇒ 可微：假"],"say":"可微就連續，這是對的。反過來，連續就可微，是錯的。","board":[{"do":"write","line":"可微 ⇒ 連續：真"},{"do":"write","line":"${{f:\\text{連續}\\Rightarrow\\text{可微}}}$：假","on":"反過來","ms":3075},{"do":"strike","term":"f","label":"錯","on":"連續就可微","ms":4038}],"t":[98316,105336]},{"show":["$f(x)=|x|$ 在 0"],"note":"連續，但不可微。","say":"反例是絕對值 x 在零：圖形連在一起，可是那裡是個尖角，不可微。逆否可以換，逆命題不能換。","board":[{"do":"clear"},{"do":"write","line":"$f(x)=|x|$","on":"絕對值","ms":625},{"do":"write","line":"在 0：連續，${{k:\\text{尖角}}}$","on":"圖形連在一起","ms":2188},{"do":"focus","term":"k","color":"red","label":"不可微","on":"尖角","ms":4650},{"do":"write","line":"逆否可換，逆命題不行","on":"逆否可以換","ms":7000}],"t":[105624,116028]},{"show":["$|x|$ 的圖在 0 轉了個彎"],"note":"沒有斷開，所以連續；尖角處沒有切線。","say":"畫出來看：左邊往下斜，右邊往上斜，在零接在一起，卻轉了個彎。","board":[{"do":"plot","graph":{"window":[-2,2,-1,2.5],"curves":[{"expr":"abs(x)","domain":[-2,2],"color":"blue"}]}}],"t":[116316,123768]}],"check":1},{"title":"或要變且","beats":[{"show":["什麼時候用逆否？"],"note":"結論的否定比較能寫成式子的時候。","say":"結論像是等於零、是偶數，它的否定反而比較好寫成式子，這時就換方向走。","board":[{"do":"write","line":"${{q:\\neg Q}}$ 好寫 ⇒ 改證 $\\neg Q\\Rightarrow\\neg P$"},{"do":"focus","term":"q","label":"結論否定","on":"否定反而","ms":3075}],"t":[124056,131832]},{"show":["證：$a+b\\ge2$ ⇒ $a\\ge1$ 或 $b\\ge1$"],"note":"結論是「或」，直接證要分情況。","say":"例子：a 加 b 大於等於二，則 a 或 b 至少一個大於等於一。直接證要分情況，很囉嗦。","board":[{"do":"write","line":"$a+b\\ge2$ ⇒ $a\\ge1$ ${{o:\\text{或}}}$ $b\\ge1$"},{"do":"underline","term":"o","label":"要分情況","on":"分情況","ms":6388}],"t":[132120,141084]},{"show":["逆否：$a<1$ 且 $b<1$ ⇒ $a+b<2$"],"note":"「或」的否定是「且」。","say":"改證逆否。或的否定要變成且：a 小於一而且 b 小於一。兩式一加，和就小於二。","board":[{"do":"write","line":"逆否：$a<1$ ${{n:\\text{且}}}$ $b<1$ ⇒ $a+b<2$"},{"do":"focus","term":"n","label":"或變且","on":"變成且","ms":2600},{"do":"write","line":"$a+b<1+1=2$","on":"兩式一加","ms":6238}],"t":[141372,150660]},{"show":["第一句：「我們證明逆否命題」"],"say":"寫的時候第一句就說明，你在證逆否命題，讀的人才知道你從哪裡出發。","board":[{"do":"clear"},{"do":"write","line":"第一句：${{s:\\text{我們證明逆否命題}}}$","on":"第一句","ms":938},{"do":"box","term":"s","color":"green","on":"逆否命題","ms":2857}],"t":[150948,158112]}],"key":"否定「或」要變成「且」","check":2},{"title":"要多小就多小","beats":[{"show":["證：對所有 $\\varepsilon>0$，$|a|<\\varepsilon$ ⇒ $a=0$"],"say":"最後一個：如果 a 的絕對值比任何正數都小，那 a 一定是零。前提很強，是對所有 epsilon。","board":[{"do":"write","line":"對所有 ${{e:\\varepsilon>0}}$：$|a|<\\varepsilon$"},{"do":"write","line":"⇒ ${{z:a=0}}$","on":"一定是零","ms":4225},{"do":"focus","term":"e","label":"前提很強","on":"前提","ms":5938}],"t":[158400,167724]},{"show":["逆否：$a\\ne0$ ⇒ 存在 $\\varepsilon>0$，$|a|\\ge\\varepsilon$"],"note":"量詞也要換：對所有變存在。","say":"改證逆否：a 不是零，就找得到一個 epsilon，讓 a 的絕對值大於等於它。量詞也跟著換了。","board":[{"do":"write","line":"逆否：$a\\ne0$ ⇒ ${{x:\\exists\\,\\varepsilon>0}}$，$|a|\\ge\\varepsilon$"},{"do":"focus","term":"x","label":"量詞換了","on":"量詞","ms":6625}],"t":[168012,176976]},{"show":["只要挑一個 $\\varepsilon$"],"note":"之後證「極限唯一」也會用到這句話。","say":"否定結論之後，我們只要挑出一個 epsilon 就好。該挑哪一個？","board":[{"do":"write","line":"只要挑一個 ${{p:\\varepsilon}}$"},{"do":"focus","term":"p","label":"挑哪個","on":"epsilon","ms":2675}],"t":[177264,183600]},{"show":["$\\varepsilon$ 要滿足兩件事"],"note":"是正數，而且 $|a|\\ge\\varepsilon$。","say":"要挑的 epsilon 有兩個條件：它得是正數，因為前提只管正的 epsilon；還要讓 a 的絕對值大於等於它。","board":[{"do":"write","line":"${{c1:\\varepsilon>0}}$"},{"do":"write","line":"${{c2:|a|\\ge\\varepsilon}}$","on":"大於等於","ms":7038}],"t":[183888,192816]},{"show":["挑好後，前提在這個 $\\varepsilon$ 上不成立"],"note":"$a\\ne0$ 時，$|a|$ 是正數。","say":"挑好之後，前提在這個 epsilon 上就不成立。a 不是零，所以 a 的絕對值是正數，可以拿來比。","board":[{"do":"write","line":"前提在這個 $\\varepsilon$ 上不成立"},{"do":"write","line":"$a\\ne0$ ⇒ ${{p1:|a|>0}}$","on":"a 不是零","ms":4500},{"do":"focus","term":"p1","color":"gold","on":"正數","ms":6800}],"t":[193104,202572]}],"check":3}],"checks":[{"ask":"「若 $x^2\\ne1$，則 $x\\ne1$」的逆否命題是？","options":[{"label":"若 $x=1$，則 $x^2=1$","correct":true},{"label":"若 $x\\ne1$，則 $x^2\\ne1$","why":"那是逆命題（前後對調但沒否定），跟原命題不等價；$x=-1$ 就是反例。"},{"label":"若 $x^2=1$，則 $x=1$","why":"那是否命題（只否定、沒對調），也不等價；$x=-1$ 讓它為假。"}]},{"ask":"「若 $f$ 可微，則 $f$ 連續」為真。下列哪一句也一定為真？","options":[{"label":"若 $f$ 不連續，則 $f$ 不可微","correct":true},{"label":"若 $f$ 連續，則 $f$ 可微","why":"這是逆命題。$f(x)=|x|$ 在 0 連續但不可微。"},{"label":"若 $f$ 不可微，則 $f$ 不連續","why":"這是否命題，跟逆命題等價，一樣被 $|x|$ 打掉。"}]},{"ask":"證「若 $ab$ 是無理數，則 $a$ 或 $b$ 是無理數」，逆否命題要從哪裡出發？","options":[{"label":"$a$ 與 $b$ 都是有理數","correct":true},{"label":"$a$ 或 $b$ 是有理數","why":"「$a$ 或 $b$ 是無理數」的否定是「$a$ 且 $b$ 都不是無理數」，或要換成且。"},{"label":"$ab$ 是有理數","why":"那是否定前提，屬於逆否命題的結論那一端，不是出發點。"}]},{"ask":"證「$|a|<\\varepsilon$ 對所有 $\\varepsilon>0\\Rightarrow a=0$」時，$a\\ne0$ 之後該取哪個 $\\varepsilon$？","options":[{"label":"$\\varepsilon=|a|$","correct":true},{"label":"$\\varepsilon=a$","why":"$a$ 可能是負的，$\\varepsilon$ 必須是正數；要取 $|a|$。"},{"label":"$\\varepsilon=0$","why":"前提只談 $\\varepsilon>0$，$\\varepsilon=0$ 不在範圍內，拿它來用不合法。"}]}],"practice":[{"id":"cg-12a-021","core":true},{"id":"cg-12a-022","core":true},{"id":"cg-12a-019","core":true},{"id":"cg-12a-020"}]},"contradiction":{"id":"contradiction","prerequisites":["contrapositive"],"next":["induction"],"related":["negation"],"objectives":["照「假設結論不成立 → 推出矛盾 → 結論成立」的骨架寫證明，並明確指出矛盾的是哪兩句。","分得清反證法與逆否證明：逆否有明確的目標 $\\neg P$，反證法只要撞到任何矛盾。","會證 $\\sqrt{2}$ 是無理數、質數有無窮多個這兩個經典結果。"],"concept":[{"heading":"① 想法：假設它錯，看看會怎樣","body":["要證命題 $Q$。先假設 $\\neg Q$，然後放手推，推到一句跟已知事實（或跟自己）衝突的話，例如「$0<0$」或「$p$ 是偶數又是奇數」。既然 $\\neg Q$ 會導出不可能的事，$\\neg Q$ 就不成立，所以 $Q$ 成立。","適合的訊號：結論是「不存在」「無理數」「無窮多個」這種否定式的說法。它們直接證很難下手，但它們的否定（存在一個、是分數 $\\frac{p}{q}$、只有有限個）給你一個具體的東西可以操作。"]},{"heading":"② 寫法","body":["第一句寫「反設 $\\neg Q$」，並把 $\\neg Q$ 照〈否定〉的規則寫清楚。最後一句寫出矛盾的兩句話各是什麼，再寫「矛盾，故 $Q$ 成立」。","反證與逆否的差別：證 $P\\Rightarrow Q$ 時，逆否是假設 $\\neg Q$、目標明確地推出 $\\neg P$；反證是同時握有 $P$ 與 $\\neg Q$，推出任何矛盾都算。如果你的矛盾恰好是「$\\neg P$」，那其實就是逆否證明，改寫成逆否會更乾淨。"]},{"heading":"③ 一個陷阱：反設要用到","body":["推出矛盾之後，回頭檢查：矛盾是不是真的用到了反設？如果沒用到反設也推得出矛盾，那是前面某一步算錯了，不是證完了。"]}],"workedExamples":[{"title":"$\\sqrt{2}$ 是無理數","prompt":"證明：不存在有理數 $r$ 使 $r^2=2$。","steps":["反設存在有理數 $r$ 使 $r^2=2$。可以設 $r>0$（$-r$ 也滿足），寫成 $r=\\frac{p}{q}$，$p$、$q$ 是正整數，而且已約到最簡（$p$、$q$ 沒有大於 1 的公因數）。","$\\frac{p^2}{q^2}=2$，所以 $p^2=2q^2$，$p^2$ 是偶數。由〈逆否證明〉的範例，$p$ 是偶數，寫成 $p=2m$。","代回去：$4m^2=2q^2$，$q^2=2m^2$，$q^2$ 是偶數，所以 $q$ 也是偶數。","$p$、$q$ 都是偶數，有公因數 2，與「已約到最簡」矛盾。故不存在這樣的 $r$。"],"answer":"反設 $\\sqrt{2}=\\frac{p}{q}$ 最簡，推出 $p$、$q$ 都是偶數，矛盾","note":"「最簡分數」能取到，是因為正整數的公因數有限，一直約下去一定會停（良序原理，見〈數學歸納法〉）。"},{"title":"沒有最小的正實數","prompt":"證明：集合 $(0,\\infty)$ 沒有最小元。","steps":["反設 $r$ 是 $(0,\\infty)$ 的最小元：$r>0$，而且對所有 $x>0$ 都有 $r\\le x$。","令 $x=\\frac{r}{2}$。$r>0$，所以 $x>0$，$x$ 屬於 $(0,\\infty)$。","由最小元的性質 $r\\le\\frac{r}{2}$，兩邊減 $\\frac{r}{2}$ 得 $\\frac{r}{2}\\le0$，也就是 $r\\le0$，與 $r>0$ 矛盾。"],"answer":"反設最小元 $r$，則 $\\frac{r}{2}$ 更小而且仍為正，矛盾","note":"$\\inf(0,\\infty)=0$ 存在，只是不屬於集合；這跟「沒有最小元」不衝突。"},{"title":"質數有無窮多個","prompt":"證明：質數有無窮多個。","steps":["反設質數只有有限個：$p_1,p_2,\\dots,p_k$。令 $N=p_1p_2\\cdots p_k+1$。","$N\\ge2$，所以 $N$ 有某個質因數 $p$。$p$ 必在清單裡，某個 $p_i=p$。","$p$ 整除 $p_1p_2\\cdots p_k$，也整除 $N$，所以整除兩者的差 $N-p_1p_2\\cdots p_k=1$。但質數 $p\\ge2$ 不能整除 1，矛盾。","注意 $N$ 本身不一定是質數：$2\\cdot3\\cdot5\\cdot7\\cdot11\\cdot13+1=30031=59\\cdot509$。證明只用到「$N$ 的質因數不在清單裡」。"],"answer":"$N=p_1\\cdots p_k+1$ 的質因數不在清單中，矛盾"}],"pitfalls":["以為 $p_1p_2\\cdots p_k+1$ 一定是質數。$30031=59\\cdot509$ 就不是。","反設沒寫清楚，或把「¬(存在)」寫成「存在 ¬」。","推出矛盾卻沒用到反設，其實是前面算錯了。","能直接寫成逆否證明的，硬寫成反證，讓結構變得難讀。"],"voice":"3cd24246","sections":[{"title":"假設它錯","beats":[{"show":["要證 $Q$：先假設 $\\neg Q$"],"note":"推到一句不可能的話，例如「$0<0$」。","say":"反證法的想法：假設結論是錯的，放手往下推，推到一句不可能成立的話。","board":[{"do":"write","line":"要證 $Q$"},{"do":"write","line":"假設 ${{n1:\\neg Q}}$ ⇒ 推到不可能","on":"假設結論","ms":1550}],"t":[0,7452]},{"show":["$\\neg Q$ 導出不可能 ⇒ $Q$ 成立"],"say":"既然結論的否定會導出不可能的事，那個否定就不成立，所以結論成立。","board":[{"do":"write","line":"${{n2:\\neg Q}}$ 導出不可能"},{"do":"strike","term":"n2","label":"不成立","on":"不成立","ms":3938},{"do":"write","line":"$Q$ 成立","color":"green","on":"所以結論","ms":4900}],"t":[7740,14796]},{"show":["訊號：不存在、無理數、無窮多個"],"note":"它們的否定給你一個具體的東西可以操作。","say":"結論是不存在、無理數、無窮多個，直接證很難下手；否定之後是一個分數、有限個，反而好算。","board":[{"do":"clear"},{"do":"write","line":"結論：不存在、無理數、無窮多個","on":"不存在","ms":675},{"do":"write","line":"否定：一個分數、有限個","on":"否定之後","ms":5313}],"t":[15084,25164]},{"show":["第一句：反設 $\\neg Q$","最後：寫出矛盾的兩句話"],"say":"寫的時候，第一句把反設照否定的規則寫清楚；最後一句說明是哪兩句話互相衝突。","board":[{"do":"write","line":"第一句：反設 $\\neg Q$"},{"do":"write","line":"最後：寫出矛盾的兩句話","on":"最後一句","ms":4238}],"t":[25452,33696]}],"check":0},{"title":"證明：$\\sqrt{2}$ 是無理數","beats":[{"show":["反設 $r=\\frac{p}{q}$，$r^2=2$","$p$、$q$ 正整數，已約到最簡"],"note":"目標：推出 $p$、$q$ 都是偶數。","say":"策略：反證。反設根號二是有理數，寫成 q 分之 p，先約到最簡，p 和 q 沒有大於一的公因數。","board":[{"do":"write","line":"反設 $\\sqrt{2}=\\frac{p}{q}$，${{pq:p,\\,q}}$ 已約到最簡","tint":{"pq":"violet"}},{"do":"underline","term":"pq","on":"約到最簡","ms":6113}],"t":[33984,44388]},{"show":["$y=x^2$ 與 $y=2$ 的交點"],"say":"畫出 y 等於 x 平方的曲線和高度二的直線，交點就是根號二。圖只看得到它存在，看不出它是不是分數。","board":[{"do":"plot","graph":{"window":[-1,3,-1,5],"curves":[{"expr":"x^2","domain":[-1,3],"color":"blue"},{"expr":"2","domain":[-1,3],"color":"red"}]}}],"t":[44676,55476]},{"show":["$p^2=2q^2$ ⇒ $p$ 是偶數"],"note":"$p^2$ 偶數 ⇒ $p$ 偶數：〈逆否證明〉的範例。","why":{"ask":"為什麼 $p$ 是偶數？","say":"p 平方是二倍的 q 平方，是偶數。為什麼 p 也是偶數？","options":[{"label":"$p^2$ 偶數 ⇒ $p$ 偶數（逆否證明）","correct":true},{"label":"$p=\\sqrt{2}\\,q$","why":"這又回到根號二，等於拿要證的東西當工具；要用的是整數的奇偶。"},{"label":"$p$ 偶數 ⇒ $p^2$ 偶數","why":"方向反了：那是從 $p$ 推 $p^2$；這裡知道的是 $p^2$，要推回 $p$。"}],"t":[55764,62280]},"say":"兩邊平方再乘過去，p 平方是偶數。上一課證過：平方是偶數，本身就是偶數。","board":[{"do":"write","line":"$p^2=2q^2$ ⇒ ${{pe:p}}$ 是偶數"},{"do":"focus","term":"pe","label":"逆否證明","why":true,"on":"上一課","ms":4250}],"t":[62568,71748]},{"show":["奇數 $2m+1$ 的平方還是奇數"],"say":"反過來看：奇數是二 m 加一，平方展開提出二後還餘一，仍是奇數。所以平方是偶數，本身只能是偶數。","board":[{"do":"write","line":"$(2m+1)^2=4m^2+4m+1$"},{"do":"write","line":"$=2(2m^2+2m)+1$","on":"提出二","ms":3675}],"t":[72036,83448]},{"show":["$p=2m$：$4m^2=2q^2$，$q^2=2m^2$"],"note":"$q^2$ 是偶數，所以 $q$ 也是偶數。","say":"把 p 寫成二 m 代回去，兩邊除以二，q 平方是二倍的 m 平方，所以 q 也是偶數。","board":[{"do":"write","line":"$p=2m$：$4m^2=2q^2$，$q^2=2m^2$"}],"t":[83736,91836]},{"show":["$p$、$q$ 都是偶數，有公因數 2"],"note":"與「已約到最簡」矛盾，反設不成立。","why":{"ask":"為什麼這樣 $\\sqrt{2}$ 就是無理數？","say":"p 和 q 都是偶數。為什麼這樣就證完了？","options":[{"label":"反設推出矛盾，所以反設不成立","correct":true},{"label":"我們找不到這樣的 $p$、$q$","why":"找不到不等於不存在；是矛盾說明根本不可能有。"},{"label":"兩個偶數本身就不可能","why":"兩個偶數完全可能；不可能的是它們又已約到最簡。"}],"t":[92124,97164]},"say":"可是一開始說好已經約到最簡了。兩句話打架，所以反設不成立，根號二是無理數。","board":[{"do":"write","line":"${{pq2:p,\\,q}}$ 都是偶數，有公因數 $2$","tint":{"pq2":"blue"}},{"do":"underline","term":"pq","color":"red","why":true,"on":"約到最簡","ms":1775},{"do":"underline","term":"pq2","color":"red","label":"矛盾","why":true,"on":"兩句話打架","ms":3638}],"t":[97452,106488]}],"key":"從 $p^2=2q^2$ 一路推出公因數 2","proof":true,"of":"ex0","skeleton":"反證","order":{"ask":"把證明排回順序：依序點每一步","steps":[{"label":"反設 $\\sqrt{2}=\\frac{p}{q}$，已約到最簡"},{"label":"$p^2=2q^2$，所以 $p$ 是偶數","why":"要先有 $p$、$q$，才寫得出 $p^2=2q^2$。"},{"label":"$p=2m$，所以 $q$ 也是偶數","why":"要先知道 $p$ 是偶數，才能寫成 $2m$。"},{"label":"與「已約到最簡」矛盾","why":"要先知道 $p$、$q$ 都是偶數，才跟最簡衝突。"}]}},{"title":"回頭檢查","beats":[{"show":["「已約到最簡」取得到嗎？"],"note":"正整數的公因數有限，一直約下去一定會停。","say":"反設的時候說已約到最簡，這取得到嗎？公因數只有有限個，一直約下去一定會停。","board":[{"do":"write","line":"「已約到最簡」取得到嗎？"},{"do":"write","line":"公因數有限 ⇒ 一直約會停","on":"公因數只有","ms":4350}],"t":[106776,115524]},{"show":["約一次就變小"],"say":"每約掉一個大於一的公因數，分子分母就變小，而正整數不能一直變小，所以約幾次一定停，停下來就是最簡。","board":[{"do":"write","line":"約一次就變小"}],"t":[115812,126324]},{"show":["回頭檢查：矛盾有用到反設嗎？"],"note":"沒用到也推得出矛盾，是前面算錯了。","say":"推出矛盾之後，回頭看一眼：如果沒用到反設也能推出矛盾，那是前面某一步算錯了，不是證完了。","board":[{"do":"write","line":"推出矛盾後：回頭看一眼"},{"do":"write","line":"沒用到反設也矛盾 ⇒ 算錯了","on":"如果沒用到","ms":2925}],"t":[126612,136224]},{"show":["沒用反設卻矛盾"],"say":"假設沒用到反設就推出矛盾，表示矛盾藏在已知事實裡。可是已知事實不會自相矛盾，所以一定是哪一步算錯。","board":[{"do":"write","line":"已知事實不矛盾"},{"do":"write","line":"⇒ 某步錯","on":"一定是","ms":8913}],"t":[136512,147816]}],"check":2},{"title":"沒有最小的正數","beats":[{"show":["證：$(0,\\infty)$ 沒有最小元"],"say":"再一個：所有正實數組成的集合，沒有最小的那一個。結論是沒有，正好用反證。","board":[{"do":"write","line":"證：$(0,\\infty)$ 沒有最小元"},{"do":"write","line":"結論是「沒有」⇒ 用反證","on":"結論是沒有","ms":5413}],"t":[148104,156852]},{"show":["反設 $r$ 是最小元"],"note":"$r>0$，而且對所有 $x>0$ 都有 $r\\le x$。","say":"反設 r 是最小元：r 是正的，而且比集合裡每一個數都小或相等。要找一個 x 來打掉它。","board":[{"do":"write","line":"反設 $r$ 是最小元"},{"do":"write","line":"${{a:r>0}}$，對所有 $x>0$：$r\\le x$","on":"r 是正的","ms":1775}],"t":[157140,166248]}],"predict":{"ask":"拿哪一個 $x$ 來打掉 $r$？","options":[{"label":"$x=\\frac{r}{2}$","correct":true},{"label":"$x=r-1$","why":"$r<1$ 時 $r-1$ 不是正數，不在集合裡，拿它比沒有用。"},{"label":"$x=0$","why":"0 不屬於 $(0,\\infty)$，最小元的性質只對 $x>0$ 說話。"}]}},{"title":"質數有無窮多個","beats":[{"show":["$x$ 要正，還要比 $r$ 小"],"note":"兩個條件同時過，才打得掉 $r$。","say":"先想為什麼挑它：要的數得是正的才在集合裡，又得比 r 小才能打掉 r。把 r 除以二，剛好兩個條件都過。","board":[{"do":"write","line":"$x>0$ 且 $x<r$"},{"do":"write","line":"取 $x=\\frac{r}{2}$","on":"除以二","ms":7213}],"t":[166536,177156]},{"show":["$r\\le\\frac{r}{2}$ ⇒ $r\\le0$"],"note":"與 $r>0$ 矛盾。","say":"二分之 r 還是正的，最小元的性質說 r 小於等於它，整理得 r 小於等於零，矛盾。","board":[{"do":"write","line":"$\\frac{r}{2}>0$"},{"do":"write","line":"$r\\le\\frac{r}{2}$","on":"最小元的性質","ms":1938},{"do":"transform","line":"${{z:r\\le0}}$","on":"整理得","ms":4600},{"do":"circle","term":"z","color":"red","label":"矛盾","on":"小於等於零","ms":5175}],"t":[177444,185328]},{"show":["反設質數只有 $p_1,p_2,\\dots,p_k$","令 $N=p_1p_2\\cdots p_k+1$"],"say":"接著證質數有無窮多個。反設只有有限個，把它們全部乘起來再加一，叫它 N。","board":[{"do":"clear"},{"do":"write","line":"反設質數只有 $p_1,p_2,\\dots,p_k$","on":"反設只有","ms":2938},{"do":"write","line":"$N=p_1p_2\\cdots p_k+1$","on":"乘起來","ms":5363}],"t":[185616,193968]},{"show":["$N$ 的質因數 $p$ 必在清單裡"],"note":"$p$ 整除 $N-p_1p_2\\cdots p_k=1$：矛盾。","say":"N 有某個質因數，它一定在清單裡，那它就同時整除乘積和 N，所以整除一。質數不能整除一。","board":[{"do":"write","line":"$N$ 的質因數 $p$ 在清單裡"},{"do":"write","line":"$p$ 整除 $N$ 與乘積 ⇒ ${{o:p\\mid 1}}$","on":"同時整除","ms":3600},{"do":"strike","term":"o","label":"不可能","on":"質數不能","ms":7438}],"t":[194256,204048]},{"show":["$a=pu$，$b=pv$ ⇒ $a-b=p(u-v)$"],"note":"這裡 $N-p_1\\cdots p_k=1$。","say":"整除的性質：p 整除 a 和 b，就能寫成 p 乘 u、p 乘 v，相減提出 p。這裡 N 減乘積剛好是一。","board":[{"do":"write","line":"$a=pu$，$b=pv$"},{"do":"write","line":"$a-b=p(u-v)$","on":"相減","ms":5188},{"do":"write","line":"$N-p_1\\cdots p_k=1$","on":"N 減乘積","ms":7525}],"t":[204336,214416]},{"show":["$N$ 不一定是質數"],"note":"$30031=59\\cdot509$。","say":"注意 N 本身不一定是質數。證明只用到：N 的質因數不在清單裡。","t":[214704,221868]}],"key":"看 $N$ 除以清單上的質數餘多少","check":1},{"title":"反證還是逆否","beats":[{"show":["逆否：假設 $\\neg Q$，目標是推出 $\\neg P$"],"say":"證若 P 則 Q 的時候，逆否是假設非 Q，目標很明確，就是推出非 P。","board":[{"do":"write","line":"逆否：假設 $\\neg Q$"},{"do":"write","line":"目標：推出 ${{np:\\neg P}}$","on":"目標很明確","ms":3613}],"t":[222156,229248]},{"show":["反證：握有 $P$ 與 $\\neg Q$，推出任何矛盾"],"say":"反證是 P 和非 Q 一起拿在手上，推出任何矛盾都算。","board":[{"do":"write","line":"反證：手上有 $P$ 與 $\\neg Q$"},{"do":"write","line":"推出任何矛盾都算","on":"推出任何","ms":3013}],"t":[229536,235008]},{"show":["矛盾恰好是 $\\neg P$？"],"note":"那其實是逆否證明，改寫會更乾淨。","say":"如果你推出的矛盾剛好就是非 P，那其實是逆否證明，照逆否的格式寫，結構比較好讀。","board":[{"do":"clear"},{"do":"write","line":"矛盾恰好是 ${{x:\\neg P}}$","on":"如果你","ms":50},{"do":"write","line":"⇒ 改寫成逆否證明","on":"那其實","ms":3000}],"t":[235296,243900]}],"check":3}],"checks":[{"ask":"用反證法證「$\\sqrt{3}$ 是無理數」，第一句應該是？","options":[{"label":"反設 $\\sqrt{3}=\\frac{p}{q}$，$p$、$q$ 是互質的正整數","correct":true},{"label":"反設 $\\sqrt{3}$ 不是 $\\frac{p}{q}$ 的形式","why":"那就是要證的結論本身，反設要假設結論的否定：$\\sqrt{3}$ 是有理數。"},{"label":"反設 $\\sqrt{3}$ 是整數","why":"「不是無理數」是「是有理數」，範圍比整數大得多；只排除整數證不到結論。"}]},{"ask":"$N=2\\cdot3\\cdot5\\cdot7\\cdot11\\cdot13+1=30031$。關於 $N$ 下列何者正確？","options":[{"label":"$N$ 不一定是質數，但它的質因數都不是 2、3、5、7、11、13","correct":true},{"label":"$N$ 一定是質數","why":"你記錯了證明的結論。$30031=59\\cdot509$，不是質數。"},{"label":"$N$ 可以被 13 整除","why":"$N$ 除以 13 餘 1（$N-1$ 是 13 的倍數），所以不能被 13 整除。"}]},{"ask":"證 $\\sqrt{2}$ 無理時，矛盾的兩句話是？","options":[{"label":"$p$、$q$ 已約到最簡，以及 $p$、$q$ 都是偶數","correct":true},{"label":"$p^2=2q^2$ 與 $p$ 是偶數","why":"這兩句不衝突，後者是由前者推出來的。"},{"label":"$\\sqrt{2}$ 是有理數與 $\\sqrt{2}$ 是無理數","why":"後者是要證的結論，不能拿來用；矛盾必須來自推導出的具體事實。"}]},{"ask":"證「若 $n^2$ 是偶數則 $n$ 是偶數」時，假設 $n$ 是奇數並推出 $n^2$ 是奇數。這比較準確地叫做？","options":[{"label":"逆否證明","correct":true},{"label":"數學歸納法","why":"沒有用到 $n$ 到 $n+1$ 的遞推，跟歸納法無關。"},{"label":"直接證明","why":"直接證明會從 $n^2$ 是偶數出發。這裡是從結論的否定出發，推到前提的否定。"}]}],"practice":[{"id":"cg-12a-024","core":true},{"id":"cg-12a-023","core":true}]},"induction":{"id":"induction","prerequisites":["contradiction"],"next":["bounds"],"related":["recursive-sequence","monotone-convergence-proof"],"objectives":["寫出完整的歸納證明：基底、歸納假設、歸納步驟，三段缺一不可。","歸納步驟從 $P(k+1)$ 的一邊出發，明確指出哪一步用了歸納假設。","會用歸納法證遞迴數列有界，並知道強歸納法什麼時候需要。"],"concept":[{"heading":"① 骨牌","body":["要證對每個 $n\\in\\mathbb{N}$，$P(n)$ 都成立。無限多個命題不能一個一個檢查，但可以檢查兩件事：第一張骨牌會倒（$P(1)$ 成立）；任何一張倒了，下一張就會倒（$P(k)\\Rightarrow P(k+1)$）。兩件事都成立，所有骨牌都會倒。（直覺，不是證明；嚴格的理由見下面的折疊段。）"]},{"heading":"② 三段式寫法","body":["基底：直接驗證 $P(1)$。","歸納假設：設 $P(k)$ 對某個 $k\\in\\mathbb{N}$ 成立。注意是「某個 $k$」，不是「所有 $k$」，否則就是假設了要證的東西。","歸納步驟：證 $P(k+1)$。從 $P(k+1)$ 的一邊出發，把它拆成「$P(k)$ 裡出現過的部分」加上「新增的部分」，用一次歸納假設，再整理成 $P(k+1)$ 的另一邊。","結論：由數學歸納法，$P(n)$ 對所有 $n\\in\\mathbb{N}$ 成立。"]},{"heading":"③ 兩個變形","body":["起點不必是 1：要證 $n\\ge5$ 時成立，基底就驗 $P(5)$。","強歸納法：歸納假設改成「$P(1),\\dots,P(k)$ 都成立」。當 $P(k+1)$ 需要的不只是前一項時用它，例如「每個 $n\\ge2$ 都有質因數」：$n+1$ 若不是質數，寫成 $ab$，$a$、$b$ 都比 $n+1$ 小，用的是 $P(a)$ 而不是 $P(n)$。"]},{"heading":"為什麼歸納法是對的：良序原理","body":["良序原理：$\\mathbb{N}$ 的每個非空子集都有最小元。（這是 $\\mathbb{N}$ 的基本性質，與歸納法互相等價。）","證明：設 $P(1)$ 成立，且對每個 $k$，$P(k)\\Rightarrow P(k+1)$。反設有某些 $n$ 使 $P(n)$ 不成立，令 $S$ 為這些 $n$ 的集合，$S$ 非空，有最小元 $m$。$m\\ne1$，因為 $P(1)$ 成立；所以 $m-1\\in\\mathbb{N}$，而且 $m-1\\notin S$（$m$ 是最小的），即 $P(m-1)$ 成立。由歸納步驟 $P(m)$ 成立，與 $m\\in S$ 矛盾。","基底不能省的例子：$P(n)$：「$n=n+1$」。若 $n=n+1$，兩邊加 1 得 $n+1=n+2$，所以 $P(k)\\Rightarrow P(k+1)$ 確實成立；但 $P(1)$ 是 $1=2$，假的，$P(n)$ 一個都不成立。"],"collapsible":true}],"workedExamples":[{"title":"前 $n$ 個奇數的和","prompt":"證明：對所有 $n\\in\\mathbb{N}$，$1+3+5+\\cdots+(2n-1)=n^2$。","problemId":"px-ind-001","steps":["基底：$n=1$，左邊 1，右邊 $1^2=1$。成立。","歸納假設：設對某個 $k\\in\\mathbb{N}$，$1+3+\\cdots+(2k-1)=k^2$。","歸納步驟：$n=k+1$ 的左邊是 $[1+3+\\cdots+(2k-1)]+(2(k+1)-1)$。方括號用歸納假設換成 $k^2$，得 $k^2+2k+1=(k+1)^2$，正是 $n=k+1$ 的右邊。","由數學歸納法，對所有 $n\\in\\mathbb{N}$ 成立。抽查 $n=5$：$1+3+5+7+9=25=5^2$。"],"answer":"得證；歸納步驟 $k^2+(2k+1)=(k+1)^2$"},{"title":"Bernoulli 不等式","prompt":"證明：$x>-1$ 時，對所有 $n\\in\\mathbb{N}$，$(1+x)^n\\ge1+nx$。","problemId":"px-ind-003","steps":["基底：$n=1$，兩邊都是 $1+x$。成立。","歸納假設：設對某個 $k$，$(1+x)^k\\ge1+kx$。","歸納步驟：$(1+x)^{k+1}=(1+x)^k\\cdot(1+x)$。因為 $x>-1$，$1+x>0$，不等式兩邊乘正數方向不變：$(1+x)^k(1+x)\\ge(1+kx)(1+x)$。","展開 $(1+kx)(1+x)=1+(k+1)x+kx^2\\ge1+(k+1)x$，因為 $kx^2\\ge0$。所以 $(1+x)^{k+1}\\ge1+(k+1)x$。"],"answer":"得證；$x>-1$ 用在「乘 $1+x>0$ 不等號不變」","note":"條件 $x>-1$ 不能拿掉：$x=-3$、$n=3$ 時 $(1+x)^3=-8$，$1+3x=-8$，剛好相等；$n=5$ 時 $(-2)^5=-32<1-15=-14$，不等式失敗。"},{"title":"遞迴數列有界","prompt":"$a_1=\\sqrt{2}$，$a_{n+1}=\\sqrt{2+a_n}$。證明對所有 $n$，$0<a_n<2$。","problemId":"lec-11-q3a","steps":["基底：$a_1=\\sqrt{2}\\approx1.414$，$0<\\sqrt{2}<2$。成立。","歸納假設：設對某個 $k$，$0<a_k<2$。","歸納步驟：$2<2+a_k<4$，$\\sqrt{\\cdot}$ 在 $[0,\\infty)$ 上嚴格遞增，所以 $\\sqrt{2}<\\sqrt{2+a_k}<\\sqrt{4}=2$，即 $0<\\sqrt{2}<a_{k+1}<2$。","由數學歸納法，對所有 $n$，$0<a_n<2$。例如 $a_2=\\sqrt{2+\\sqrt{2}}\\approx1.848<2$。"],"answer":"得證；歸納步驟用 $\\sqrt{\\cdot}$ 的遞增性","note":"有界再加上遞增，就能用〈單調收斂定理（嚴格版）〉得到收斂，見〈遞迴數列〉。"}],"pitfalls":["沒寫基底。只有歸納步驟的「證明」可以證出 $n=n+1$。","歸納假設寫成「設對所有 $k$ 成立」，等於假設結論。","歸納步驟從 $P(k+1)$ 的兩邊同時往中間湊，最後寫「兩邊相等」，看不出用了哪個等式。","某一步只在 $k\\ge2$ 才對，基底卻只驗 $n=1$，中間那一格斷了（「所有馬同一個顏色」的錯誤就在 $k=1\\to2$）。"],"voice":"b164e81f","sections":[{"title":"骨牌","beats":[{"show":["對每個 $n\\in\\mathbb{N}$，$P(n)$ 成立"],"note":"無限多個命題，不能一個一個檢查。","say":"要證對每一個自然數 n 都成立。無限多句話不可能一句一句檢查，那檢查什麼？","board":[{"do":"write","line":"對每個 $n\\in\\mathbb{N}$，$P(n)$ 成立"},{"do":"write","line":"無限多個命題，不能一個一個檢查","on":"無限多句話","ms":3363}],"t":[0,8136]},{"show":["第一張會倒：$P(1)$","倒了推下一張：$P(k)\\Rightarrow P(k+1)$"],"say":"想成一排骨牌。第一張會倒，而且任何一張倒了都會推倒下一張，那全部都會倒。","board":[{"do":"write","line":"第一張會倒：$P(1)$"},{"do":"write","line":"倒了推下一張：$P(k)\\Rightarrow P(k+1)$","on":"任何一張","ms":3900}],"t":[8424,16956]},{"show":["只有推倒那一步：$n=n+1$"],"note":"$P(k)\\Rightarrow P(k+1)$ 成立，但 $P(1)$ 是 $1=2$。","say":"這是直覺，不是證明。但它說明了基底不能省：n 等於 n 加一，每一步都推得下去，可是第一張根本沒倒。","board":[{"do":"clear"},{"do":"write","line":"直覺，不是證明","color":"red","on":"這是直覺","ms":50},{"do":"write","line":"$n=n+1$：每一步都推得下去","on":"n 等於 n 加一","ms":5100}],"t":[17244,28008]}],"check":0},{"title":"證明：良序原理","beats":[{"show":["反設有反例，取最小的那一個"],"note":"良序原理：$\\mathbb{N}$ 的非空子集有最小元。","say":"骨牌只是直覺。真正的證明用反證：假設有命題不成立，挑最小的那個反例，推出矛盾。","board":[{"do":"write","line":"反證：假設有反例，挑最小的"}],"t":[28296,37836]},{"show":["$S$：使 $P(n)$ 不成立的 $n$","$S$ 非空，有最小元 $m$"],"note":"良序原理。","why":{"ask":"為什麼 $S$ 一定有最小元？","say":"反例的集合 S 可能很大。為什麼一定挑得出最小的那個？","options":[{"label":"良序原理：$\\mathbb{N}$ 的非空子集都有最小元","correct":true},{"label":"$S$ 是有限集合","why":"$S$ 可能有無限多個元素；靠的是 $\\mathbb{N}$ 的良序，不是有限。"},{"label":"$P(1)$ 成立","why":"$P(1)$ 成立只說 $1$ 不在 $S$ 裡；最小元存在要靠良序原理。"}],"t":[38124,44316]},"say":"S 是自然數的非空子集，良序原理保證它有最小元，叫它 m。","board":[{"do":"write","line":"$S$：使 $P(n)$ 不成立的 $n$"},{"do":"write","line":"$S$ 非空 ⇒ 最小元 ${{m:m}}$","tint":{"m":"violet"},"on":"最小的那個","ms":4288},{"do":"underline","term":"m","label":"良序原理","why":true,"on":"良序原理","ms":2388}],"t":[44604,50940]},{"show":["$m\\ne1$，所以 $m-1\\in\\mathbb{N}$"],"note":"$P(1)$ 成立，$1$ 不在 $S$ 裡。","say":"m 不會是一，因為 P 一成立。所以 m 減一還是自然數。","board":[{"do":"keep","n":2},{"do":"write","line":"${{m:m}}\\ne1$ ⇒ $m-1\\in\\mathbb{N}$","on":"m 不會是一","ms":50}],"t":[51228,57456]},{"show":["$m-1\\notin S$：$P(m-1)$ 成立"],"note":"$m$ 是 $S$ 裡最小的。","why":{"ask":"為什麼 $P(m-1)$ 成立？","say":"m 減一這個命題，為什麼一定成立？","options":[{"label":"$m$ 是 $S$ 的最小元，比 $m$ 小的不在 $S$ 裡","correct":true},{"label":"由歸納假設","why":"這裡正在證歸納法本身，沒有歸納假設可用；靠的是 $m$ 最小。"},{"label":"$m-1<m$，越小越容易成立","why":"命題沒有「越小越容易」這回事；是 $m$ 的最小性讓 $m-1$ 不在 $S$ 裡。"}],"t":[57744,61524]},"say":"m 是最小的反例，比它小的 m 減一就不是反例，所以 P 在 m 減一成立。","board":[{"do":"write","line":"${{m1:m-1}}\\notin S$：$P(m-1)$ 成立"},{"do":"underline","term":"m1","label":"比 m 小","why":true,"on":"比它小","ms":1738}],"t":[61812,68580]},{"show":["比 $m$ 小的，都不在 $S$ 裡"],"note":"$S$ 裡放的是不成立的 $n$。","say":"m 是最小的反例，意思是比 m 小的數，全都不在 S 裡。m 減一比 m 小，所以不是反例，P 就成立。","board":[{"do":"focus","term":"m1","color":"gold","label":"不在 S"}],"t":[68868,79020]},{"show":["歸納步驟 ⇒ $P(m)$ 成立","與 $m\\in S$ 矛盾"],"say":"再用歸納步驟推一格，P 在 m 也成立，可是 m 是反例。矛盾，所以根本沒有反例。","board":[{"do":"keep","n":1},{"do":"write","line":"歸納步驟 ⇒ $P({{m:m}})$ 成立","on":"歸納步驟","ms":450},{"do":"write","line":"與 ${{m:m}}\\in S$ 矛盾","color":"green","on":"矛盾","ms":5500}],"t":[79308,88128]}],"key":"取最小反例 $m$，往前一格 $m-1$ 成立","proof":true,"of":3,"skeleton":"反證","where":{"ask":"基底 $P(1)$ 用在哪一步？","steps":[{"label":"$S$ 非空，有最小元 $m$","why":"這一步只用到反設（$S$ 非空）和良序原理。"},{"label":"$m\\ne1$，所以 $m-1\\in\\mathbb{N}$","correct":true},{"label":"$m-1\\notin S$：$P(m-1)$ 成立","why":"這一步只用到 $m$ 是最小元。"},{"label":"$P(m)$ 成立，矛盾","why":"這一步只用到歸納步驟 $P(k)\\Rightarrow P(k+1)$。"}]}},{"title":"三段式寫法","beats":[{"show":["基底：驗證 $P(1)$"],"say":"寫法固定三段。第一段基底，直接驗 n 等於一。","board":[{"do":"write","line":"基底：驗證 $P(1)$"}],"t":[88416,94032]},{"show":["歸納假設：$P(k)$ 對某個 $k$ 成立"],"note":"是「某個 $k$」，不是「所有 $k$」。","say":"第二段，假設對某一個 k 成立。不能寫所有 k，那等於假設了要證的東西。","board":[{"do":"write","line":"歸納假設：$P(k)$ 對某個 $k$ 成立"},{"do":"write","line":"${{w:\\forall k,\\ P(k)}}$","on":"不能寫所有","ms":3613},{"do":"strike","term":"w","label":"不能寫","on":"那等於假設","ms":5013}],"t":[94320,102240]},{"show":["歸納步驟：證 $P(k+1)$"],"note":"拆成「$P(k)$ 有的部分」＋「新增的部分」。","say":"第三段證 k 加一。把它拆成上一個命題已經有的部分，加上新增的那一塊。","board":[{"do":"write","line":"歸納步驟：證 ${{t:P(k+1)}}$"},{"do":"underline","term":"t","label":"拆成兩塊","on":"拆成","ms":2650}],"t":[102528,110376]},{"show":["代數字：$k=3$，$[1+3+5]+7$"],"note":"前三項是舊的，$7$ 是新增的。","say":"先代個數看看：k 等於三，前三項是一加三加五，新增的第四項是七。","board":[{"do":"write","line":"$k=3$：${{q:[1+3+5]}}$＋$7$"},{"do":"underline","term":"q","label":"歸納假設","on":"前三項","ms":2763}],"t":[110664,118008]},{"show":["$1+3+5+\\cdots+(2n-1)=n^2$"],"note":"歸納假設：前 $k$ 個奇數和是 $k^2$。","say":"例子：前 n 個奇數加起來是 n 平方。到 k 加一的時候，左邊是前 k 項，再加一個新的奇數。","board":[{"do":"clear"},{"do":"write","line":"$1+3+5+\\cdots+(2n-1)=n^2$","on":"前 n 個","ms":888},{"do":"write","line":"$k+1$：${{a:[1+3+\\cdots+(2k-1)]}}$＋新的奇數","on":"到 k 加一","ms":4200},{"do":"underline","term":"a","label":"前 k 項","on":"前 k 項","ms":6263}],"t":[118296,127980]}],"key":"新增的是第 $k+1$ 項，不是第 $k$ 項","predict":{"ask":"方括號換成 $k^2$ 之後，左邊是？","options":[{"label":"$k^2+2k+1=(k+1)^2$","correct":true},{"label":"$k^2+(2k-1)$","why":"$2k-1$ 是第 $k$ 項，已經在方括號裡了；新增的是 $2(k+1)-1=2k+1$。"},{"label":"$k^2+2(k+1)$","why":"新增的奇數是 $2(k+1)-1$，最後的減 1 漏掉了。"}]}},{"title":"乘正數方向不變","beats":[{"show":["抽查 $n=5$：$1+3+5+7+9=25=5^2$"],"say":"剛好是 k 加一的平方，證完了。順手抽查 n 等於五：二十五，正是五的平方。","board":[{"do":"write","line":"$1+3+5+7+9=25$","on":"抽查","ms":4125},{"do":"transform","line":"$1+3+5+7+9=25={{sq:5^2}}$","on":"正是","ms":6500}],"t":[128268,136800]},{"show":["$x>-1$：$(1+x)^n\\ge1+nx$"],"note":"基底 $n=1$：兩邊都是 $1+x$。","say":"再一個不等式，條件是 x 大於負一。n 等於一的時候兩邊一樣，基底沒問題。","board":[{"do":"clear"},{"do":"write","line":"${{c:x>-1}}$：$(1+x)^n\\ge1+nx$","on":"不等式","ms":600},{"do":"write","line":"基底 $n=1$：兩邊都是 $1+x$","on":"n 等於一","ms":3975}],"t":[137088,145440]},{"show":["$(1+x)^{k+1}=(1+x)^k(1+x)$","$\\ge(1+kx)(1+x)$"],"say":"拆出一個一加 x，對歸納假設兩邊同乘它。不等號方向不變，需要什麼條件？","board":[{"do":"keep","n":1},{"do":"write","line":"$(1+x)^{k+1}=(1+x)^k{{m:(1+x)}}$","on":"拆出","ms":50},{"do":"write","line":"$\\ge(1+kx){{m:(1+x)}}$","on":"同乘","ms":2888},{"do":"focus","term":"m","on":"方向不變","ms":5013}],"t":[145728,153936]},{"show":["$=1+(k+1)x+kx^2\\ge1+(k+1)x$"],"note":"因為 $kx^2\\ge0$。","say":"展開後多出 k 乘 x 平方，它不是負的，丟掉只會變小，就得到 k 加一的情形。","board":[{"do":"write","line":"$=1+(k+1)x+{{kx:kx^2}}$","on":"展開","ms":50},{"do":"underline","term":"kx","label":"不是負的","on":"不是負的","ms":2675},{"do":"transform","line":"$=1+(k+1)x+{{kx:kx^2}}\\ge 1+(k+1)x$","on":"丟掉","ms":3738}],"t":[154224,162036]}],"key":"把 $(1+x)^{k+1}$ 拆成 $(1+x)^k(1+x)$","check":1},{"title":"遞迴數列有界","beats":[{"show":["$a_1=\\sqrt{2}$，$a_{n+1}=\\sqrt{2+a_n}$"],"note":"證對所有 $n$，$0<a_n<2$。","say":"第一項根號二，下一項是根號二加前一項。要證每一項都夾在零和二之間。","board":[{"do":"write","line":"$a_1=\\sqrt{2}$，$a_{n+1}=\\sqrt{2+a_n}$"},{"do":"write","line":"證：${{goal:0<a_n<2}}$","on":"要證","ms":4613}],"t":[162324,170424]},{"show":["基底：$0<\\sqrt{2}<2$"],"note":"$\\sqrt{2}\\approx1.414$。","say":"根號二大約一點四一四，在零和二之間，基底成立。","board":[{"do":"write","line":"基底：$0<\\sqrt{2}\\approx1.414<2$"}],"t":[170712,176256]},{"show":["假設 $0<a_k<2$ ⇒ $2<2+a_k<4$"],"note":"根號在 $[0,\\infty)$ 上嚴格遞增。","say":"假設第 k 項夾在零和二之間，加二之後夾在二和四之間。接著開根號，方向保持。","board":[{"do":"write","line":"假設 $0<a_k<2$ ⇒ ${{r:2<2+a_k<4}}$"},{"do":"underline","term":"r","on":"加二之後","ms":2775}],"t":[176544,185832]},{"show":["$\\sqrt{2+x}$ 隨 $x$ 增加而上升"],"say":"畫出來：x 越大，根號二加 x 越大，曲線一路往上爬，所以根號是遞增的。","board":[{"do":"plot","graph":{"window":[0,4,0,3],"curves":[{"expr":"sqrt(2+x)","domain":[0,4],"color":"blue"}],"dashed":[[[0,2],[4,2]]]}}],"t":[186120,194040]},{"show":["$\\sqrt{2+a_k}>\\sqrt{2}>0$"],"note":"下界：$2+a_k>2$，開根號仍大於 $\\sqrt{2}$。","say":"下界先看：二加 a k 大於二，開根號大於根號二，而根號二大於零。","board":[{"do":"write","line":"$\\sqrt{2+a_k}>\\sqrt{2}>0$"}],"t":[194328,201384]}],"check":3},{"title":"兩個變形","beats":[{"show":["起點不必是 1"],"note":"要證 $n\\ge5$ 時成立，基底就驗 $P(5)$。","say":"第一個變形：起點不一定是一。只要證 n 大於等於五，就從五開始驗。","board":[{"do":"write","line":"起點不必是 $1$"},{"do":"write","line":"$n\\ge5$：基底驗 ${{b:P(5)}}$","on":"n 大於等於五","ms":3988},{"do":"focus","term":"b","on":"從五","ms":5488}],"t":[201672,209160]},{"show":["強歸納：$P(1),\\dots,P(k)$ 都成立"],"note":"$P(k+1)$ 需要的不只前一項時用。","say":"第二個是強歸納法：假設前面每一個都成立，不只前一個。","board":[{"do":"write","line":"強歸納法：不只用前一個"}],"t":[209448,215280]},{"show":["每個 $n\\ge2$ 都有質因數"],"note":"$n+1=ab$，用的是 $P(a)$，不是 $P(n)$。","say":"例如每個大於等於二的數都有質因數。n 加一不是質數就拆成 a 乘 b，要用的是比它小的 a，不是 n。","board":[{"do":"clear"},{"do":"write","line":"每個 $n\\ge2$ 都有質因數","on":"每個大於等於二","ms":425},{"do":"write","line":"$n+1=ab$：用 ${{pa:P(a)}}$","on":"拆成","ms":5413},{"do":"underline","term":"pa","label":"比 n 小","on":"比它小","ms":7313}],"t":[215568,225540]},{"show":["中間斷一格：所有馬同一個顏色"],"note":"錯在 $k=1\\to2$ 那一步。","say":"還要小心：某一步只在 k 大於等於二才對，基底卻只驗一，中間那一格就斷了。","board":[{"do":"write","line":"基底只驗 $P(1)$，步驟要 $k\\ge2$"},{"do":"write","line":"斷在 ${{g:k=1\\to2}}$ 這一步","on":"中間","ms":5413},{"do":"circle","term":"g","color":"red","label":"斷了","on":"那一格","ms":5800}],"t":[225828,233640]},{"show":["$k=1$：兩群各一匹，沒有共同的馬"],"say":"具體看：兩群馬要有共同的馬才接得起來。k 等於一時兩群各一匹，沒有交集，推不到二。","board":[{"do":"write","line":"$k=1$：兩群各一匹，沒有共同的馬","color":"red"}],"t":[233928,243504]},{"show":["驗 $P(2)$：兩匹馬可以不同色"],"note":"$P(2)$ 是假的，基底多驗一格就現形。","say":"所以還要驗 P 二：兩匹馬可以不同色，P 二是假的，斷口一驗就現形。","board":[{"do":"write","line":"驗 $P(2)$：兩匹馬可以不同色"}],"t":[243792,251136]}],"check":2}],"checks":[{"ask":"某人證「所有 $n$ 都有 $P(n)$」，只證了 $P(k)\\Rightarrow P(k+1)$。結論是？","options":[{"label":"還沒證完，缺基底；$P(n)$ 可能一個都不成立","correct":true},{"label":"證完了，因為每一步都推得下去","why":"骨牌每張都會推倒下一張，但第一張沒倒，什麼都不會發生。$n=n+1$ 就是反例。"},{"label":"只證到 $n=1$","why":"連 $n=1$ 都沒證，那正是缺少的基底。"}]},{"ask":"Bernoulli 不等式的歸納步驟，哪一步用到 $x>-1$？","options":[{"label":"不等式兩邊乘 $1+x$ 時，需要 $1+x>0$","correct":true},{"label":"$kx^2\\ge0$ 那一步","why":"平方乘正整數 $k$ 永遠 $\\ge0$，與 $x$ 的範圍無關。"},{"label":"基底 $n=1$","why":"$n=1$ 時兩邊相等，對任何 $x$ 都成立，不需要條件。"}]},{"ask":"強歸納法的歸納假設是？","options":[{"label":"$P(1),P(2),\\dots,P(k)$ 都成立","correct":true},{"label":"$P(k)$ 對所有 $k$ 成立","why":"那就是要證的結論，不能假設。"},{"label":"只有 $P(k)$ 成立","why":"那是一般歸納法。強歸納法的差別正是可以用到前面所有項。"}]},{"ask":"$a_1=\\sqrt{2}$，$a_{n+1}=\\sqrt{2+a_n}$。若歸納假設是 $a_k<2$，下一步得到？","options":[{"label":"$a_{k+1}<\\sqrt{4}=2$","correct":true},{"label":"$a_{k+1}<2+2=4$","why":"你忘了開根號：$a_{k+1}=\\sqrt{2+a_k}$，不是 $2+a_k$。這個界太鬆，接不上下一步。"},{"label":"$a_{k+1}>2$","why":"不等號方向弄反了；$\\sqrt{\\cdot}$ 遞增保持方向，$a_k<2$ 推出 $\\sqrt{2+a_k}<\\sqrt{4}$。"}]}],"practice":[{"id":"px-ind-001","core":true},{"id":"px-ind-002","core":true},{"id":"px-ind-003","core":true},{"id":"lec-11-q3a","core":true},{"id":"cg-12a-025"},{"id":"cg-12a-026"},{"id":"lec-12-q4a","challenge":true,"note":"挑戰：$H_{2^{k+1}}$ 比 $H_{2^k}$ 多 $2^k$ 項，每項至少 $\\frac{1}{2^{k+1}}$。"}]}});
